def save_raw_u16_tiff(image_raw, path: Path) -> None:
    """Save one untouched PCO uint16 frame as an uncompressed 16-bit TIFF."""
    if np is None or Image is None:
        raise RuntimeError("保存16-bit图像需要 numpy 和 Pillow")
    array = np.asarray(image_raw)
    if array.ndim != 2:
        raise RuntimeError(f"原始相机帧必须是二维灰度图，当前 shape={array.shape}")
    if array.dtype != np.uint16:
        raise RuntimeError(
            f"拒绝改变原始位深：相机返回 {array.dtype}，预期 uint16"
        )
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    Image.fromarray(array).save(destination, format="TIFF", compression="raw")


def save_processed_f32_tiff(image_processed, path: Path) -> None:
    """Save signed processed difference values without applying display CLim."""
    if np is None or Image is None:
        raise RuntimeError("保存处理图像需要 numpy 和 Pillow")
    array = np.asarray(image_processed, dtype=np.float32)
    if array.ndim != 2:
        raise RuntimeError(f"处理图像必须是二维灰度图，当前 shape={array.shape}")
    if not np.all(np.isfinite(array)):
        raise RuntimeError("处理图像包含 NaN 或无穷值，已拒绝保存")
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    # Pillow stores a float32 array as TIFF mode F, preserving negative values.
    Image.fromarray(array).save(destination, format="TIFF", compression="raw")


def save_display_u8_png(image_display, path: Path) -> None:
    """Save the marker-free 8-bit image currently mapped into Camera Live."""
    if np is None or Image is None:
        raise RuntimeError("保存当前显示图片需要 numpy 和 Pillow")
    array = np.asarray(image_display)
    if array.ndim != 2 or array.dtype != np.uint8:
        raise RuntimeError(
            f"当前显示图片格式异常：dtype={array.dtype}, shape={array.shape}"
        )
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    Image.fromarray(array, mode="L").save(destination, format="PNG")


