def _find_mfli_legacy_python() -> Path:
    """Locate and validate the exact Python 3.7/LabOne 18.12 environment."""
    configured = os.environ.get(NONLOCAL_MFLI_LEGACY_PYTHON_ENV, "").strip()
    candidates = []
    if configured:
        candidates.append(Path(configured.strip('"')))
    system_drive = os.environ.get("SystemDrive", "C:")
    drive_root = Path(
        system_drive + os.sep if system_drive.endswith(":") else system_drive
    )
    user_profile = os.environ.get("USERPROFILE", "")
    local_app_data = os.environ.get("LOCALAPPDATA", "")
    if local_app_data:
        candidates.append(
            Path(local_app_data) / "NBB/MOKE_MFLI_PY37/python.exe"
        )
    candidates.append(
        Path(__file__).resolve().parent / ".mfli_py37/python.exe"
    )
    candidates.extend(
        (
            drive_root
            / "ProgramData/miniconda3/envs/GMS_VENV_PYTHON/python.exe",
            drive_root
            / "ProgramData/anaconda3/envs/GMS_VENV_PYTHON/python.exe",
        )
    )
    if user_profile:
        candidates.extend(
            (
                Path(user_profile)
                / "miniconda3/envs/GMS_VENV_PYTHON/python.exe",
                Path(user_profile)
                / "anaconda3/envs/GMS_VENV_PYTHON/python.exe",
            )
        )
    rejected = []
    validation_code = (
        "import sys,pkg_resources,numpy,zhinst,zhinst.utils;"
        "v=pkg_resources.get_distribution('zhinst').version;"
        "assert sys.version_info[:2]==(3,7),sys.version;"
        "assert v=='18.12.59443',v;"
        "assert numpy.__version__=='1.21.6',numpy.__version__;print(v)"
    )
    for candidate in candidates:
        try:
            if not candidate.is_file():
                continue
            check = subprocess.run(
                [str(candidate), "-c", validation_code],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8.0,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            if check.returncode == 0:
                return candidate
            detail = (check.stderr or check.stdout or "验证失败").strip()
            rejected.append(f"{candidate}（{short_status_error(detail, 160)}）")
        except (OSError, subprocess.SubprocessError) as error:
            rejected.append(f"{candidate}（{short_status_error(error, 160)}）")
            continue
    searched = "；".join(str(path) for path in candidates)
    rejected_text = "；".join(rejected) if rejected else "无"
    raise RuntimeError(
        "找不到通过验证的 Python 3.7 + zhinst 18.12.59443 环境。请先运行 "
        r"INSTALL_MFLI_LABONE_18_12.bat，或确认 "
        r"C:\ProgramData\miniconda3\envs\GMS_VENV_PYTHON\python.exe "
        f"存在，或设置环境变量 {NONLOCAL_MFLI_LEGACY_PYTHON_ENV}。"
        f"已检查：{searched}。不合格环境：{rejected_text}"
    )


class LegacyMFLIBridge:
    """JSON-line bridge from the Python 3.11 GUI to old zhinst/Python 3.7."""

    def __init__(self, device_id: str, timeout_s: float = 20.0) -> None:
        self.python_path = _find_mfli_legacy_python()
        self.process = None
        self.responses: queue.Queue = queue.Queue()
        self.diagnostics: list[str] = []
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        command = [
            str(self.python_path),
            "-u",
            "-c",
            _MFLI_BRIDGE_SOURCE,
            str(device_id),
            str(NONLOCAL_MFLI_API_LEVEL),
            str(NONLOCAL_MFLI_DEMODULATOR),
        ]
        try:
            self.process = subprocess.Popen(
                command,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                bufsize=1,
                creationflags=creationflags,
            )
            threading.Thread(
                target=self._read_stdout,
                name="MFLI-bridge-stdout",
                daemon=True,
            ).start()
            threading.Thread(
                target=self._read_stderr,
                name="MFLI-bridge-stderr",
                daemon=True,
            ).start()
            ready = self._receive(timeout_s)
            if ready.get("event") != "ready":
                raise RuntimeError(f"MFLI 桥接启动回复异常：{ready!r}")
            self.device = str(ready.get("device", device_id)).strip().lower()
            self.version = str(ready.get("version", ""))
            self.options = str(ready.get("options", ""))
            self.has_demod_2 = bool(ready.get("has_demod_2", False))
            self.identity = str(ready.get("identity", self.device))
        except BaseException:
            self.close(force=True)
            raise

    def _append_diagnostic(self, line: str) -> None:
        line = str(line).strip()
        if not line:
            return
        self.diagnostics.append(line)
        del self.diagnostics[:-12]

    def _read_stdout(self) -> None:
        stream = self.process.stdout if self.process is not None else None
        if stream is None:
            self.responses.put({"_eof": True})
            return
        try:
            for raw_line in stream:
                line = raw_line.rstrip("\r\n")
                if line.startswith(_MFLI_BRIDGE_PREFIX):
                    try:
                        self.responses.put(
                            json.loads(line[len(_MFLI_BRIDGE_PREFIX):])
                        )
                    except BaseException as error:
                        self._append_diagnostic(f"JSON 解析失败：{error}: {line}")
                else:
                    self._append_diagnostic(line)
        finally:
            self.responses.put({"_eof": True})

    def _read_stderr(self) -> None:
        stream = self.process.stderr if self.process is not None else None
        if stream is None:
            return
        for line in stream:
            self._append_diagnostic(line)

    def _diagnostic_suffix(self) -> str:
        if not self.diagnostics:
            return ""
        return "；旧环境输出：" + " | ".join(self.diagnostics[-5:])

    def _receive(self, timeout_s: float) -> dict[str, object]:
        try:
            reply = self.responses.get(timeout=max(0.1, float(timeout_s)))
        except queue.Empty as error:
            raise RuntimeError(
                f"旧版 LabOne 桥接在 {timeout_s:g} s 内没有回复"
                + self._diagnostic_suffix()
            ) from error
        if reply.get("_eof"):
            exit_code = self.process.poll() if self.process is not None else None
            raise RuntimeError(
                f"旧版 LabOne 桥接意外退出（code={exit_code}）"
                + self._diagnostic_suffix()
            )
        if not reply.get("ok"):
            detail = str(reply.get("error", "未知错误")).strip()
            raise RuntimeError(
                "旧版 LabOne 桥接失败：" + detail + self._diagnostic_suffix()
            )
        return reply

    def request(
        self, command: str, timeout_s: float = 10.0, **parameters
    ) -> dict[str, object]:
        if self.process is None or self.process.poll() is not None:
            raise RuntimeError(
                "旧版 LabOne 桥接未运行" + self._diagnostic_suffix()
            )
        if self.process.stdin is None:
            raise RuntimeError("旧版 LabOne 桥接 stdin 不可用")
        payload = {"command": str(command)}
        payload.update(parameters)
        try:
            self.process.stdin.write(json.dumps(payload, ensure_ascii=True) + "\n")
            self.process.stdin.flush()
        except (BrokenPipeError, OSError) as error:
            raise RuntimeError(
                "无法向旧版 LabOne 桥接发送命令" + self._diagnostic_suffix()
            ) from error
        return self._receive(timeout_s)

    def close(self, force: bool = False) -> None:
        process = self.process
        if process is None:
            return
        if process.poll() is None and not force:
            try:
                self.request("close", timeout_s=5.0)
                try:
                    process.wait(timeout=2.0)
                except subprocess.TimeoutExpired:
                    force = True
            except BaseException:
                force = True
        if process.poll() is None and force:
            try:
                process.terminate()
                process.wait(timeout=2.0)
            except BaseException:
                try:
                    process.kill()
                except BaseException:
                    pass
        for stream in (process.stdin, process.stdout, process.stderr):
            try:
                if stream is not None:
                    stream.close()
            except BaseException:
                pass
        self.process = None


class NonLocalACController:
    """Own one 6221 plus independently selectable voltage instruments."""

    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.resource_manager = None
        self.source = None
        self.lockins: dict[str, object] = {}
        self.mfli_daq = None
        self.mfli_bridge: LegacyMFLIBridge | None = None
        self.mfli_device = ""
        self.mfli_props: dict[str, object] = {}
        self.mfli_config: dict[str, object] = {}
        self.nanovoltmeter = None
        self.source_identity = ""
        self.lockin_identities: dict[str, str] = {}
        self.mfli_identity = ""
        self.nanovoltmeter_identity = ""
        self.source_resource = ""
        self.lockin_resources: dict[str, str] = {}
        self.nanovoltmeter_resource = ""
        self.mfli_lease_resource = ""
        self.output_enabled = False
        self.source_output_mode = "AC"
        self.lock = threading.RLock()
        self.sensitivity_indices: dict[str, int] = {}
        self.low_range_counts: dict[str, int] = {}
        self.range_cooldowns: dict[str, int] = {}
        self.mfli_low_range_count = 0
        self.mfli_range_cooldown = 0
        self.mfli_initial_autorange_pending = False

    @property
    def connected(self) -> bool:
        return self.source is not None and (
            bool(self.lockins)
            or self.mfli_connected
            or self.nanovoltmeter is not None
        )

    @property
    def source_connected(self) -> bool:
        return self.source is not None

    @property
    def any_connected(self) -> bool:
        return (
            self.source is not None
            or bool(self.lockins)
            or self.mfli_connected
            or self.nanovoltmeter is not None
        )

    @property
    def shared_source_lockin_connected(self) -> bool:
        """6221/SR830 devices shared with other pages (MFLI is independent)."""
        return (
            self.source is not None
            or bool(self.lockins)
        )

    @property
    def nanovoltmeter_connected(self) -> bool:
        return self.nanovoltmeter is not None

    @property
    def mfli_connected(self) -> bool:
        return self.mfli_daq is not None or self.mfli_bridge is not None

    def lockin_connected(self, key: str) -> bool:
        return str(key) in self.lockins

    @property
    def connected_lockin_keys(self) -> tuple[str, ...]:
        return tuple(sorted(self.lockins, key=int))

    @staticmethod
    def _configure_transport(instrument) -> None:
        instrument.timeout = 5000
        instrument.write_termination = "\n"
        instrument.read_termination = "\n"
        # SR830/GPIB replies are unreliable when a read follows the query
        # write with no processing delay; the next query can then consume the
        # previous reply (most visibly the *IDN? string).  50 ms is short
        # relative to the measurement cadence and prevents that reply shift.
        try:
            instrument.query_delay = 0.05
        except (AttributeError, ValueError):
            pass

    @staticmethod
    def _query_float(instrument, command: str) -> float:
        return float(instrument.query(command).strip())

    def _write_6221(self, command: str) -> None:
        self.source.write(command)
        time.sleep(0.03)
        response = self.source.query("SYST:ERR?").strip()
        try:
            code = int(response.split(",", 1)[0].strip())
        except ValueError as error:
            raise RuntimeError(f"6221 错误状态无法解析：{response}") from error
        if code != 0:
            raise RuntimeError(f"6221 在 {command!r} 后报错：{response}")

    def _write_sr830(self, key: str, command: str) -> None:
        lockin = self.lockins[key]
        lockin.write(command)
        time.sleep(0.03)
        event_status = int(self._query_sr830_numbers(key, "*ESR?", 1)[0])
        if event_status & 0x30:
            raise RuntimeError(
                f"SR830 #{key} 拒绝 {command!r}；*ESR?={event_status}"
            )

    def _write_2182(self, command: str) -> None:
        meter = self.nanovoltmeter
        if meter is None:
            raise RuntimeError("Keithley 2182A 尚未连接")
        meter.write(command)
        time.sleep(0.03)
        response = meter.query("SYST:ERR?").strip()
        try:
            code = int(response.split(",", 1)[0].strip())
        except ValueError as error:
            raise RuntimeError(f"2182A 错误状态无法解析：{response}") from error
        if code != 0:
            raise RuntimeError(f"2182A 在 {command!r} 后报错：{response}")

    def configure_nanovoltmeter(
        self, channel: int = 1, nplc: float = 1.0
    ) -> dict[str, object]:
        """Configure 2182A using the verified standalone reference sequence."""
        with self.lock:
            if self.nanovoltmeter is None:
                raise RuntimeError("Keithley 2182A 尚未连接")
            if channel not in (1, 2):
                raise ValueError("2182A 通道必须是 1 或 2")
            if not 0.01 <= float(nplc) <= 60.0:
                raise ValueError("2182A NPLC 必须在 0.01–60 内")
            meter = self.nanovoltmeter
            meter.timeout = 10000
            meter.write("*RST")
            meter.write("*CLS")
            for command in (
                ":SENS:FUNC 'VOLT'",
                f":SENS:CHAN {channel}",
                f":SENS:VOLT:NPLC {float(nplc):.12g}",
                # The 2182A manual recommends both autozero stages for
                # low-level accuracy.  They cost speed, which is acceptable
                # for the present 1 Hz transport acquisition.
                ":SYST:AZER:STAT ON",
                ":SYST:FAZ:STAT ON",
                ":FORM:ELEM READ",
                f":SENS:VOLT:CHAN{channel}:RANG:AUTO ON",
            ):
                self._write_2182(command)
            time.sleep(0.5)
            return {
                "resource": "GPIB 7",
                "channel": channel,
                "nplc": float(nplc),
                "autozero": True,
                "front_autozero": True,
                # 2182A is a DC nanovoltmeter.  In a 6221 sine-wave run its
                # direct READ? result is useful as a DC monitor only; it must
                # not be interpreted as a phase-sensitive AC amplitude.
                "measurement_mode": "DC voltage (not phase-sensitive)",
            }

    def read_nanovoltmeter(self) -> float:
        with self.lock:
            if self.nanovoltmeter is None:
                raise RuntimeError("Keithley 2182A 尚未连接")
            response = self.nanovoltmeter.query(":READ?").strip()
            try:
                value = float(response.split(",", 1)[0].strip())
            except ValueError as error:
                raise RuntimeError(
                    f"2182A :READ? 返回无法解析：{response!r}"
                ) from error
            if not math.isfinite(value):
                raise RuntimeError(f"2182A 返回非有限电压：{response!r}")
            return value

    def _query_sr830_numbers(
        self,
        key: str,
        command: str,
        expected_count: int,
    ) -> tuple[float, ...]:
        """Query numeric SR830 data, recovering from one stale GPIB reply."""
        lockin = self.lockins[key]
        last_response = ""
        last_error: BaseException | None = None
        for attempt in range(1, 4):
            try:
                last_response = lockin.query(command).strip()
                values = tuple(
                    float(part.strip()) for part in last_response.split(",")
                )
                if len(values) != expected_count:
                    raise ValueError(
                        f"期望 {expected_count} 个数值，收到 {len(values)} 个"
                    )
                return values
            except Exception as error:
                last_error = error
                if attempt >= 3:
                    break
                self.logger(
                    f"SR830 #{key} 查询 {command!r} 收到错位回复 "
                    f"{last_response!r}；清空缓冲后重试 {attempt}/2"
                )
                try:
                    lockin.clear()
                except Exception:
                    pass
                time.sleep(0.08)
        raise RuntimeError(
            f"SR830 #{key} 查询 {command!r} 连续返回非数字/异常回复："
            f"{last_response!r}"
        ) from last_error

    def _ensure_resource_manager(self):
        if pyvisa is None:
            raise RuntimeError("缺少 pyvisa；请运行：py -m pip install pyvisa pyvisa-py")
        if self.resource_manager is None:
            self.resource_manager = pyvisa.ResourceManager()
        return self.resource_manager

    def _close_manager_if_unused(self) -> None:
        if (
            self.source is not None
            or self.lockins
            or self.nanovoltmeter is not None
            or self.resource_manager is None
        ):
            return
        try:
            self.resource_manager.close()
        finally:
            self.resource_manager = None

    def connect_source(self, resource: str) -> str:
        """Connect only the 6221, preserving any connected SR830 devices."""
        with self.lock:
            if self.source is not None:
                return self.source_identity
            acquire_instrument_lease(resource, self, "Non-local 6221")
            source = None
            try:
                manager = self._ensure_resource_manager()
                source = manager.open_resource(resource)
                self._configure_transport(source)
                identity = source.query("*IDN?").strip()
                if "6221" not in identity.upper():
                    raise RuntimeError(f"{resource} 不是 Keithley 6221：{identity}")
                try:
                    source.clear()
                except Exception:
                    pass
                source.write("OUTP OFF")
                self.source = source
                self.source_identity = identity
                self.source_resource = resource
                self.output_enabled = False
                self.logger(f"Non-local IV 6221 已连接：{identity}")
                return identity
            except BaseException:
                if source is not None:
                    try:
                        source.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise

    def connect_lockin(self, key: str, resource: str) -> str:
        """Connect one SR830 without changing the 6221 or the other SR830."""
        key = str(key)
        if key not in ("8", "9"):
            raise ValueError(f"不支持的 SR830 编号：{key}")
        with self.lock:
            if key in self.lockins:
                return self.lockin_identities[key]
            acquire_instrument_lease(resource, self, f"Non-local SR830 #{key}")
            lockin = None
            try:
                manager = self._ensure_resource_manager()
                lockin = manager.open_resource(resource)
                self._configure_transport(lockin)
                lockin.write("OUTX 1")
                identity = lockin.query("*IDN?").strip()
                if "SR830" not in identity.upper():
                    raise RuntimeError(f"{resource} 不是 SR830：{identity}")
                # Discard a delayed identity reply before numeric queries start.
                try:
                    lockin.clear()
                except Exception:
                    pass
                lockin.write("OUTX 1")
                time.sleep(0.05)
                self.lockins[key] = lockin
                self.lockin_identities[key] = identity
                self.lockin_resources[key] = resource
                self.sensitivity_indices.pop(key, None)
                self.low_range_counts.pop(key, None)
                self.range_cooldowns.pop(key, None)
                self.logger(f"Non-local IV SR830 #{key} 已连接：{identity}")
                return identity
            except BaseException:
                if lockin is not None:
                    try:
                        lockin.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise

    def connect_nanovoltmeter(self, resource: str) -> str:
        """Connect the optional Keithley 2182A without changing other devices."""
        with self.lock:
            if self.nanovoltmeter is not None:
                return self.nanovoltmeter_identity
            acquire_instrument_lease(resource, self, "Non-local Keithley 2182A")
            meter = None
            try:
                manager = self._ensure_resource_manager()
                meter = manager.open_resource(resource)
                self._configure_transport(meter)
                identity = meter.query("*IDN?").strip()
                if "2182" not in identity.upper():
                    raise RuntimeError(f"{resource} 不是 Keithley 2182A：{identity}")
                try:
                    meter.clear()
                except Exception:
                    pass
                meter.write("*CLS")
                self.nanovoltmeter = meter
                self.nanovoltmeter_identity = identity
                self.nanovoltmeter_resource = resource
                self.logger(f"Non-local IV Keithley 2182A 已连接：{identity}")
                return identity
            except BaseException:
                if meter is not None:
                    try:
                        meter.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise

    @staticmethod
    def _mfli_reachable_servers(
        timeout_s: float = 1.2,
    ) -> tuple[list[tuple[str, int]], list[str]]:
        """Return reachable LabOne endpoints without entering a 20 s API wait."""
        reachable = []
        diagnostics = []
        for host, port in NONLOCAL_MFLI_SERVER_CANDIDATES:
            try:
                with socket.create_connection((host, int(port)), timeout_s):
                    reachable.append((host, int(port)))
                    diagnostics.append(f"{host}:{port}=TCP可达")
            except OSError as error:
                diagnostics.append(f"{host}:{port}=不可达（{error}）")
        return reachable, diagnostics

    def connect_mfli(self, device_id: str) -> str:
        """Prefer the current Python API, with the legacy bridge as fallback."""
        requested = str(device_id).strip().lower()
        if not requested:
            raise ValueError("请输入 Zurich MFLI API 设备名，例如 dev4435")
        if requested.startswith("mf-"):
            requested = requested[3:]
        with self.lock:
            if self.mfli_connected:
                return self.mfli_identity
            direct_errors: list[str] = []
            reachable_servers, tcp_diagnostics = self._mfli_reachable_servers()
            self.logger("MFLI 网络预检：" + "；".join(tcp_diagnostics))

            # Do not start Core/Discovery or search for another Python when no
            # LabOne Data Server is listening.  Neither a pip install nor a
            # legacy interpreter can repair a disconnected USB/RNDIS link.
            if not reachable_servers:
                diagnostic_text = "；".join(tcp_diagnostics)
                raise RuntimeError(
                    "Zurich MFLI Data Server 当前不可达，程序尚未进入 "
                    "LabOne API 握手。\n\n"
                    f"快速检测：{diagnostic_text}\n\n"
                    "请依次检查：\n"
                    "1. MFLI 已开机，并用后面板 USB Device 口连接电脑；\n"
                    "2. Windows 的 USB/RNDIS 网卡已启用，电脑地址应为 "
                    "192.168.69.77；\n"
                    "3. PowerShell 执行：ping 192.168.69.78；\n"
                    "4. 执行：Test-NetConnection 192.168.69.78 -Port 8004。\n\n"
                    "只有 TcpTestSucceeded=True 后，Python API 才可能连接。"
                )

            mfli_lease_resource = f"LABONE::{requested}"
            acquire_instrument_lease(
                mfli_lease_resource, self, "Non-local Zurich MFLI"
            )
            self.mfli_lease_resource = mfli_lease_resource

            # LabOne 18.12 only published a CPython 3.7 wheel.  Prefer the
            # installer-created, version-exact bridge when it exists; the GUI,
            # camera, VISA and all other modules remain in the current Python.
            bridge = None
            try:
                bridge = LegacyMFLIBridge(requested)
                self.mfli_daq = None
                self.mfli_bridge = bridge
                self.mfli_device = bridge.device
                self.mfli_props = {
                    "serverversion": bridge.version,
                    "connection": "labone-18.12-python37-bridge",
                    "python": str(bridge.python_path),
                    "options": bridge.options,
                    "has_demod_2": bridge.has_demod_2,
                }
                self.mfli_config = {}
                self.mfli_identity = bridge.identity
                self.logger(
                    "Non-local Zurich MFLI 已通过精确匹配的 LabOne 18.12 "
                    f"环境连接：{bridge.identity}"
                )
                return bridge.identity
            except BaseException as bridge_error:
                if bridge is not None:
                    bridge.close(force=True)
                direct_errors.append(f"18.12 Python 3.7 桥接：{bridge_error}")
                self.logger(
                    "精确匹配的 LabOne 18.12 桥接暂不可用，继续尝试当前 "
                    f"Python 的本机 API：{bridge_error}"
                )

            # Then try version-matched native APIs installed with LabOne or its
            # LabVIEW driver. Both adapters run inside this Python process.
            if sys.platform == "win32":
                native_adapters = (
                    ("LabOne C API", LabOneCAPIAdapter,
                     "current-python-labone-c-api"),
                    ("LabOne .NET", LabOneDotNetAdapter,
                     "current-python-labone-dotnet"),
                )
                for adapter_label, adapter_class, connection_name in native_adapters:
                    for server_host, server_port in reachable_servers:
                        daq = None
                        try:
                            daq = adapter_class(
                                server_host,
                                server_port,
                                NONLOCAL_MFLI_API_LEVEL,
                            )
                            sample_node = (
                                f"/{requested}/demods/"
                                f"{NONLOCAL_MFLI_DEMODULATOR}/sample"
                            )
                            enable_node = (
                                f"/{requested}/demods/"
                                f"{NONLOCAL_MFLI_DEMODULATOR}/enable"
                            )
                            try:
                                daq.setInt(enable_node, 1)
                                daq.sync()
                                daq.getSample(sample_node)
                            except BaseException as initial_error:
                                attachment_errors = [f"已挂接读取：{initial_error}"]
                                for interface in ("PCIe", "1GbE", "USB"):
                                    try:
                                        daq.connectDevice(requested, interface)
                                        daq.setInt(enable_node, 1)
                                        daq.sync()
                                        daq.getSample(sample_node)
                                        break
                                    except BaseException as attach_error:
                                        attachment_errors.append(
                                            f"{interface}: {attach_error}"
                                        )
                                else:
                                    raise RuntimeError(
                                        "Data Server 已连接，但无法读取 DEV4435："
                                        + " | ".join(attachment_errors)
                                    )
                            version = ""
                            for version_node in (
                                "/zi/about/version",
                                "/zi/about/revision",
                            ):
                                try:
                                    version = str(daq.getString(version_node)).strip()
                                except BaseException:
                                    continue
                                if version:
                                    break
                            identity_parts = ["Zurich Instruments MFLI", requested]
                            if version:
                                identity_parts.append(f"LabOne {version}")
                            identity = " · ".join(identity_parts)
                            self.mfli_daq = daq
                            self.mfli_bridge = None
                            self.mfli_device = requested
                            self.mfli_props = {
                                "serveraddress": server_host,
                                "serverport": server_port,
                                "serverversion": version,
                                "connection": connection_name,
                                "api_dll": str(daq.api_dll),
                            }
                            self.mfli_config = {}
                            self.mfli_identity = identity
                            self.logger(
                                "Non-local Zurich MFLI 已由当前 Python 加载 "
                                f"{adapter_label}：{identity} @ "
                                f"{server_host}:{server_port}"
                            )
                            return identity
                        except BaseException as error:
                            direct_errors.append(
                                f"{adapter_label} {server_host}:{server_port}："
                                f"{error}"
                            )
                            if daq is not None:
                                try:
                                    daq.disconnect()
                                except BaseException:
                                    pass
                            self.logger(
                                f"当前 Python 加载 {adapter_label} 连接 "
                                f"{server_host}:{server_port} 失败：{error}"
                            )

            # Modern Core remains a secondary path, useful after LabOne is
            # upgraded or when the matching .NET API was not installed.
            if zi_core is not None:
                for server_host, server_port in reachable_servers:
                    if server_host == NONLOCAL_MFLI_SERVER_HOST:
                        direct_errors.append(
                            "新版 Core：已跳过已确认运行 LabOne 18.12.59443 "
                            f"的 {server_host}:{server_port}，避免重复等待 20 s"
                        )
                        continue
                    daq = None
                    try:
                        daq = zi_core.ziDAQServer(
                            server_host,
                            server_port,
                            NONLOCAL_MFLI_API_LEVEL,
                            allow_version_mismatch=True,
                        )
                        sample_node = (
                            f"/{requested}/demods/"
                            f"{NONLOCAL_MFLI_DEMODULATOR}/sample"
                        )
                        try:
                            visible_nodes = daq.listNodes(
                                f"/{requested}", recursive=False, absolute=True
                            )
                        except TypeError:
                            visible_nodes = daq.listNodes(f"/{requested}", 0)
                        if not visible_nodes:
                            attachment_errors = []
                            for interface in ("PCIe", "1GbE", "USB"):
                                try:
                                    daq.connectDevice(requested, interface)
                                    break
                                except BaseException as attach_error:
                                    attachment_errors.append(
                                        f"{interface}: {attach_error}"
                                    )
                            else:
                                raise RuntimeError(
                                    "Data Server 已连接，但无法挂接设备："
                                    + " | ".join(attachment_errors)
                                )
                        daq.setInt(
                            f"/{requested}/demods/"
                            f"{NONLOCAL_MFLI_DEMODULATOR}/enable",
                            1,
                        )
                        daq.sync()
                        daq.getSample(sample_node)
                        version = ""
                        for version_node in (
                            "/zi/about/version",
                            "/zi/about/revision",
                        ):
                            try:
                                version = str(daq.getString(version_node)).strip()
                            except BaseException:
                                continue
                            if version:
                                break
                        identity_parts = ["Zurich Instruments MFLI", requested]
                        if version:
                            identity_parts.append(f"LabOne {version}")
                        identity = " · ".join(identity_parts)
                        self.mfli_daq = daq
                        self.mfli_bridge = None
                        self.mfli_device = requested
                        self.mfli_props = {
                            "serveraddress": server_host,
                            "serverport": server_port,
                            "serverversion": version,
                            "connection": "current-python-core",
                            "allow_version_mismatch": True,
                        }
                        self.mfli_config = {}
                        self.mfli_identity = identity
                        self.logger(
                            "Non-local Zurich MFLI 已由当前 Python Core API "
                            f"直接连接：{identity} @ {server_host}:{server_port}"
                        )
                        return identity
                    except BaseException as error:
                        direct_errors.append(
                            f"Core {server_host}:{server_port}：{error}"
                        )
                        if daq is not None:
                            try:
                                daq.disconnect()
                            except BaseException:
                                pass
                        self.logger(
                            f"当前 Python Core API 连接 {server_host}:{server_port} "
                            f"失败：{error}"
                        )

            # Discovery is only worth attempting after a server endpoint has
            # replied.  Otherwise it adds another long timeout without adding
            # diagnostic value.
            if zi_core is None and zi_utils is not None and reachable_servers:
                daq = None
                try:
                    session = zi_utils.create_api_session(
                        requested, NONLOCAL_MFLI_API_LEVEL
                    )
                    if not isinstance(session, tuple) or len(session) < 3:
                        raise RuntimeError(
                            f"create_api_session 返回格式异常：{session!r}"
                        )
                    daq, discovered, props = session[:3]
                    device = str(discovered).strip().lower()
                    if not device:
                        raise RuntimeError("LabOne Discovery 未返回 MFLI 设备名")
                    daq.setInt(
                        f"/{device}/demods/"
                        f"{NONLOCAL_MFLI_DEMODULATOR}/enable",
                        1,
                    )
                    daq.sync()
                    daq.getSample(
                        f"/{device}/demods/"
                        f"{NONLOCAL_MFLI_DEMODULATOR}/sample"
                    )
                    identity_parts = ["Zurich Instruments MFLI", device]
                    if isinstance(props, dict):
                        version = props.get("serverversion") or props.get("version")
                        if version:
                            identity_parts.append(f"LabOne {version}")
                    identity = " · ".join(identity_parts)
                    self.mfli_daq = daq
                    self.mfli_bridge = None
                    self.mfli_device = device
                    self.mfli_props = (
                        dict(props) if isinstance(props, dict) else {}
                    )
                    self.mfli_props["connection"] = "current-python-discovery"
                    self.mfli_config = {}
                    self.mfli_identity = identity
                    self.logger(
                        "Non-local Zurich MFLI 已由当前 Python Discovery "
                        f"连接：{identity}"
                    )
                    return identity
                except BaseException as error:
                    direct_errors.append(f"Discovery：{error}")
                    if daq is not None:
                        try:
                            daq.disconnect()
                        except BaseException:
                            pass
                    self.logger(
                        "当前 Python Discovery 失败，最后尝试旧环境桥接："
                        f"{error}"
                    )

            direct_detail = " | ".join(direct_errors)
            release_instrument_lease(self.mfli_lease_resource, self)
            self.mfli_lease_resource = ""
            raise RuntimeError(
                "Zurich MFLI 的 TCP 8004 已可达，但 LabOne API 握手失败。\n"
                f"连接诊断：{direct_detail}\n\n"
                "该仪器运行 LabOne 18.12.59443；请先关闭本程序，运行同目录 "
                "INSTALL_MFLI_LABONE_18_12.bat，安装完成后重启程序。"
            )

    @staticmethod
    def _mfli_scalar(value, field: str) -> float:
        """Extract one finite scalar from old/new LabOne sample containers."""
        try:
            candidate = value[field]
        except (KeyError, TypeError) as error:
            raise RuntimeError(f"MFLI sample 缺少 {field!r} 字段") from error
        if np is not None:
            array = np.asarray(candidate).reshape(-1)
            if array.size == 0:
                raise RuntimeError(f"MFLI sample 的 {field!r} 字段为空")
            result = float(array[-1])
        elif isinstance(candidate, (tuple, list)):
            if not candidate:
                raise RuntimeError(f"MFLI sample 的 {field!r} 字段为空")
            result = float(candidate[-1])
        else:
            result = float(candidate)
        if not math.isfinite(result):
            raise RuntimeError(f"MFLI sample 的 {field!r} 字段不是有限数值")
        return result

    def configure_mfli(
        self,
        coupling: str,
        harmonic: int,
        channel: str,
        reference_source: str = NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT,
        sample_rate_hz: float = NONLOCAL_SAMPLE_HZ,
        input_impedance: str = "10 MΩ",
        input_scaling: float = NONLOCAL_MFLI_INPUT_SCALING,
    ) -> dict[str, object]:
        """Route the selected external reference, then configure Demod 1."""
        if not self.mfli_connected:
            raise RuntimeError("Zurich MFLI 尚未连接")
        coupling = str(coupling).strip().upper()
        channel = str(channel).strip().upper()
        reference_source = str(reference_source).strip()
        harmonic = int(harmonic)
        sample_rate_hz = float(sample_rate_hz)
        input_impedance = str(input_impedance).strip()
        input_scaling = float(input_scaling)
        if coupling not in {"AC", "DC"}:
            raise ValueError("MFLI 输入耦合只能选择 AC 或 DC")
        if harmonic < 1:
            raise ValueError("MFLI 倍频必须是正整数")
        if not math.isfinite(sample_rate_hz) or sample_rate_hz <= 0:
            raise ValueError("MFLI 采样率必须是有限正数")
        transfer_rate_hz = max(10.0, min(1000.0, sample_rate_hz * 5.0))
        if channel not in {"X", "Y", "R"}:
            raise ValueError("MFLI 读取通道只能选择 X、Y 或 R")
        if reference_source not in NONLOCAL_MFLI_REFERENCE_INPUTS:
            choices = "、".join(NONLOCAL_MFLI_REFERENCE_INPUTS)
            raise ValueError(f"MFLI 外参考接口必须选择：{choices}")
        impedance_choices = {"10 MΩ": 0, "50 Ω": 1}
        if input_impedance not in impedance_choices:
            raise ValueError("MFLI Signal Input 1 输入阻抗只能选择 10 MΩ 或 50 Ω")
        requested_imp50 = impedance_choices[input_impedance]
        if not math.isfinite(input_scaling) or input_scaling <= 0:
            raise ValueError("MFLI Signal Input 1 Scaling 必须是有限正数")
        reference_adcselect = NONLOCAL_MFLI_REFERENCE_INPUTS[
            reference_source
        ]
        options_text = str(self.mfli_props.get("options", "")).upper()
        has_demod_2 = bool(self.mfli_props.get("has_demod_2", False))
        if self.mfli_bridge is None and not options_text:
            try:
                options_text = str(
                    self.mfli_daq.getString(
                        f"/{self.mfli_device}/features/options"
                    )
                ).upper()
                self.mfli_props["options"] = options_text
            except BaseException:
                pass
        if self.mfli_bridge is None and not has_demod_2:
            try:
                self.mfli_daq.getInt(
                    f"/{self.mfli_device}/demods/"
                    f"{NONLOCAL_MFLI_EXTREF_DEMODULATOR}/enable"
                )
                has_demod_2 = True
            except BaseException:
                has_demod_2 = False
            self.mfli_props["has_demod_2"] = has_demod_2
        # MF-MD provides a second demodulator that can act as the external-
        # reference PLL while Demod 1 measures Signal Input 1. On a base MFLI
        # the External Reference block performs that routing with Demod 1.
        has_multi_demod = (
            ("MD" in options_text) if options_text else has_demod_2
        )
        extref_demod = (
            NONLOCAL_MFLI_EXTREF_DEMODULATOR
            if has_multi_demod
            else NONLOCAL_MFLI_DEMODULATOR
        )
        if self.mfli_bridge is not None:
            reply = self.mfli_bridge.request(
                "configure",
                coupling=coupling,
                harmonic=harmonic,
                extref_demod=extref_demod,
                reference_adcselect=reference_adcselect,
                timeconstant_s=NONLOCAL_LOCKIN_TIME_CONSTANT_S,
                filter_order=NONLOCAL_LOCKIN_FILTER_ORDER,
                sample_rate_hz=transfer_rate_hz,
                input_imp50=requested_imp50,
                input_scaling=input_scaling,
            )
            actual_ac = int(reply["actual_ac"])
            actual_imp50 = int(reply["actual_imp50"])
            actual_scaling = float(reply["actual_scaling"])
            actual_harmonic = int(reply["actual_harmonic"])
            actual_extref_harmonic = int(reply["actual_extref_harmonic"])
            extref_enabled = int(reply["extref_enabled"])
            extref_adcselect = int(reply["extref_adcselect"])
            actual_timeconstant = float(reply["timeconstant_s"])
            actual_filter_order = int(reply["filter_order"])
            actual_sample_rate = float(reply["sample_rate_hz"])
            input_range_v = float(reply["input_range_v"])
        else:
            device = self.mfli_device
            demod = NONLOCAL_MFLI_DEMODULATOR
            extref = NONLOCAL_MFLI_EXTREF_CHANNEL
            ac_node = f"/{device}/sigins/0/ac"
            imp50_node = f"/{device}/sigins/0/imp50"
            scaling_node = f"/{device}/sigins/0/scaling"
            harmonic_node = f"/{device}/demods/{demod}/harmonic"
            enable_node = f"/{device}/demods/{demod}/enable"
            osc_node = f"/{device}/demods/{demod}/oscselect"
            extref_demod_node = f"/{device}/extrefs/{extref}/demodselect"
            extref_auto_node = f"/{device}/extrefs/{extref}/automode"
            extref_enable_node = f"/{device}/extrefs/{extref}/enable"
            extref_adc_node = f"/{device}/extrefs/{extref}/adcselect"
            measurement_adc_node = f"/{device}/demods/{demod}/adcselect"
            timeconstant_node = f"/{device}/demods/{demod}/timeconstant"
            order_node = f"/{device}/demods/{demod}/order"
            rate_node = f"/{device}/demods/{demod}/rate"
            self.mfli_daq.setInt(ac_node, 1 if coupling == "AC" else 0)
            self.mfli_daq.setInt(imp50_node, requested_imp50)
            self.mfli_daq.setDouble(scaling_node, input_scaling)
            ext_demod_node = (
                f"/{device}/demods/{extref_demod}/adcselect"
            )
            ext_osc_node = (
                f"/{device}/demods/{extref_demod}/oscselect"
            )
            ext_harmonic_node = (
                f"/{device}/demods/{extref_demod}/harmonic"
            )
            ext_demod_enable_node = (
                f"/{device}/demods/{extref_demod}/enable"
            )
            self.mfli_daq.setInt(ext_demod_node, reference_adcselect)
            self.mfli_daq.setInt(ext_osc_node, 0)
            # With MF-MD, Demod 2 is only the phase detector for the external
            # reference PLL.  Keep its harmonic at 1 so oscillator 1 locks to
            # the fundamental.  Demod 1 independently applies the requested
            # measurement harmonic (for example 2ω).
            if extref_demod != demod:
                self.mfli_daq.setInt(ext_harmonic_node, 1)
            self.mfli_daq.setInt(ext_demod_enable_node, 1)
            selected_extref_input = int(
                self.mfli_daq.getInt(ext_demod_node)
            )
            # With MF-MD, Demod 2 is the PLL phase detector and Demod 1
            # remains the measurement demodulator. Without MF-MD, extrefs/0
            # performs the one-demodulator External Reference switch itself.
            try:
                self.mfli_daq.setInt(extref_demod_node, extref_demod)
            except BaseException:
                # Some LabOne 18.12 builds expose this node as read-only; the
                # selected Aux-input demodulator is still detected by extrefs.
                pass
            try:
                self.mfli_daq.setInt(extref_auto_node, 4)
            except BaseException:
                pass
            self.mfli_daq.setInt(extref_enable_node, 1)
            if extref_demod == demod:
                self.mfli_daq.sync()
                if selected_extref_input != reference_adcselect:
                    raise RuntimeError(
                        f"MFLI 单解调器外参未能选择 {reference_source}："
                        f"期望 {reference_adcselect}，回读 "
                        f"{selected_extref_input}"
                    )
                self.mfli_daq.setInt(measurement_adc_node, 0)
            self.mfli_daq.setInt(osc_node, 0)
            self.mfli_daq.setInt(harmonic_node, harmonic)
            self.mfli_daq.setDouble(
                timeconstant_node, NONLOCAL_LOCKIN_TIME_CONSTANT_S
            )
            self.mfli_daq.setInt(order_node, NONLOCAL_LOCKIN_FILTER_ORDER)
            self.mfli_daq.setDouble(rate_node, transfer_rate_hz)
            self.mfli_daq.setInt(enable_node, 1)
            self.mfli_daq.sync()
            actual_ac = int(self.mfli_daq.getInt(ac_node))
            actual_imp50 = int(self.mfli_daq.getInt(imp50_node))
            actual_scaling = float(
                self.mfli_daq.getDouble(scaling_node)
            )
            actual_harmonic = int(self.mfli_daq.getInt(harmonic_node))
            actual_extref_harmonic = (
                int(self.mfli_daq.getInt(ext_harmonic_node))
                if extref_demod != demod
                else 1
            )
            extref_enabled = int(self.mfli_daq.getInt(extref_enable_node))
            input_range_v = float(
                self.mfli_daq.getDouble(f"/{device}/sigins/0/range")
            )
            actual_timeconstant = float(
                self.mfli_daq.getDouble(timeconstant_node)
            )
            actual_filter_order = int(self.mfli_daq.getInt(order_node))
            actual_sample_rate = float(self.mfli_daq.getDouble(rate_node))
            if extref_demod != demod:
                try:
                    selected_extref_input = int(
                        self.mfli_daq.getInt(extref_adc_node)
                    )
                except BaseException:
                    pass
            extref_adcselect = selected_extref_input
        if actual_ac != (1 if coupling == "AC" else 0):
            raise RuntimeError(f"MFLI AC/DC 回读不符：{actual_ac}")
        if actual_imp50 != requested_imp50:
            raise RuntimeError(
                "MFLI Signal Input 1 输入阻抗回读不符："
                f"期望{input_impedance}，imp50={actual_imp50}"
            )
        if not math.isclose(
            actual_scaling,
            input_scaling,
            rel_tol=1e-9,
            abs_tol=1e-12,
        ):
            raise RuntimeError(
                "MFLI Signal Input 1 Scaling回读不符："
                f"期望{input_scaling:g}，回读{actual_scaling:g}"
            )
        if actual_harmonic != harmonic:
            raise RuntimeError(
                f"MFLI 倍频回读不符：请求 {harmonic}，回读 {actual_harmonic}"
            )
        if actual_extref_harmonic != 1:
            raise RuntimeError(
                "MFLI 外参考PLL倍频必须为1："
                f"回读 {actual_extref_harmonic}"
            )
        if extref_enabled != 1:
            raise RuntimeError(
                f"MFLI {reference_source} 外部参考未成功启用"
            )
        if extref_adcselect != reference_adcselect:
            raise RuntimeError(
                "MFLI 外部参考输入回读不符："
                f"期望 {reference_source}({reference_adcselect})，"
                f"回读 {extref_adcselect}"
            )
        if not math.isclose(
            actual_timeconstant,
            NONLOCAL_LOCKIN_TIME_CONSTANT_S,
            rel_tol=0.05,
            abs_tol=1e-6,
        ):
            raise RuntimeError(
                f"MFLI 时间常数回读不符：{actual_timeconstant:g} s"
            )
        if actual_filter_order != NONLOCAL_LOCKIN_FILTER_ORDER:
            raise RuntimeError(
                f"MFLI 滤波阶数回读不符：{actual_filter_order}"
            )
        if not math.isfinite(actual_sample_rate) or actual_sample_rate < sample_rate_hz:
            raise RuntimeError(
                f"MFLI 数据传输率不足：{actual_sample_rate:g} Sa/s"
            )
        self.mfli_config = {
            "meter_type": "MFLI",
            "resource": self.mfli_device,
            "coupling": "AC" if actual_ac else "DC",
            "harmonic": actual_harmonic,
            "channel": channel,
            "reference_source": reference_source,
            "reference_adcselect": reference_adcselect,
            "extref_channel": NONLOCAL_MFLI_EXTREF_CHANNEL,
            "extref_demodulator": extref_demod,
            "extref_harmonic": actual_extref_harmonic,
            "input_range_v": input_range_v,
            "input_impedance": input_impedance,
            "input_scaling": actual_scaling,
            "auto_range": True,
            "timeconstant_s": actual_timeconstant,
            "filter_order": actual_filter_order,
            "sample_rate_hz": actual_sample_rate,
        }
        self.mfli_low_range_count = 0
        self.mfli_range_cooldown = 0
        self.mfli_initial_autorange_pending = True
        return dict(self.mfli_config)

    def read_mfli(self, expected_frequency_hz: float) -> dict[str, object]:
        if not self.mfli_connected:
            raise RuntimeError("Zurich MFLI 尚未连接")
        if self.mfli_bridge is not None:
            sample = self.mfli_bridge.request("read")["sample"]
        else:
            sample = self.mfli_daq.getSample(
                f"/{self.mfli_device}/demods/"
                f"{NONLOCAL_MFLI_DEMODULATOR}/sample"
            )
            sample = dict(sample)
            try:
                sample["extref_locked"] = int(
                    self.mfli_daq.getInt(
                        f"/{self.mfli_device}/extrefs/"
                        f"{NONLOCAL_MFLI_EXTREF_CHANNEL}/locked"
                    )
                )
            except BaseException:
                sample["extref_locked"] = None
            range_node = f"/{self.mfli_device}/sigins/0/range"
            max_node = f"/{self.mfli_device}/sigins/0/max"
            min_node = f"/{self.mfli_device}/sigins/0/min"
            sample["input_range_v"] = float(
                self.mfli_daq.getDouble(range_node)
            )
            try:
                sample["input_max_normalized"] = float(
                    self.mfli_daq.getDouble(max_node)
                )
                sample["input_min_normalized"] = float(
                    self.mfli_daq.getDouble(min_node)
                )
                self.mfli_daq.setDouble(max_node, 0.0)
                self.mfli_daq.setDouble(min_node, 0.0)
            except BaseException:
                sample["input_max_normalized"] = None
                sample["input_min_normalized"] = None
        x = self._mfli_scalar(sample, "x")
        y = self._mfli_scalar(sample, "y")
        r = math.hypot(x, y)
        phase_deg = math.degrees(math.atan2(y, x))
        harmonic = int(self.mfli_config.get("harmonic", 1))
        reported_frequency = math.nan
        try:
            reported_frequency = self._mfli_scalar(sample, "frequency")
            # LabOne generations differ in whether this sample field is
            # described as oscillator/reference frequency or effective demod
            # frequency.  Accept either representation and normalize the CSV
            # value back to the 6221 fundamental.
            candidates = (reported_frequency, reported_frequency / max(harmonic, 1))
            reference_frequency = min(
                candidates,
                key=lambda value: abs(value - expected_frequency_hz),
            )
        except RuntimeError:
            reference_frequency = float(expected_frequency_hz)
        frequency_valid = math.isclose(
            reference_frequency,
            expected_frequency_hz,
            rel_tol=5e-3,
            abs_tol=0.1,
        )
        raw_extref_locked = sample.get("extref_locked")
        extref_locked = (
            None if raw_extref_locked is None else bool(round(float(raw_extref_locked)))
        )
        reference_valid = frequency_valid and extref_locked is not False
        try:
            flags = int(round(self._mfli_scalar(sample, "flags")))
        except RuntimeError:
            flags = 0
        status_parts = []
        if flags:
            status_parts.append(f"LabOne flags={flags}")
        if extref_locked is False:
            reference_source = str(
                self.mfli_config.get(
                    "reference_source",
                    NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT,
                )
            )
            status_parts.append(f"{reference_source} 外部参考未锁定")
        elif extref_locked is None and frequency_valid:
            status_parts.append("LabOne 18.12 按参考频率收敛判定 LOCK")
        if not frequency_valid:
            status_parts.append("参考频率不符")
        input_range_v = self._mfli_scalar(sample, "input_range_v")
        input_extrema = []
        for field in ("input_max_normalized", "input_min_normalized"):
            try:
                input_extrema.append(abs(self._mfli_scalar(sample, field)))
            except (RuntimeError, TypeError, ValueError):
                pass
        input_utilization = (
            max(input_extrema)
            if input_extrema
            else min(1.0, abs(r) / max(input_range_v, 1e-30))
        )
        return {
            "meter_type": "MFLI",
            "voltage": {"X": x, "Y": y, "R": r}.get(
                str(self.mfli_config.get("channel", "R")), r
            ),
            "X": x,
            "Y": y,
            "R": r,
            "phase_deg": phase_deg,
            "reference_frequency_hz": reference_frequency,
            "demodulation_frequency_hz": reported_frequency,
            "reference_source": str(
                self.mfli_config.get(
                    "reference_source",
                    NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT,
                )
            ),
            "extref_locked": extref_locked,
            "lia_status": flags | (0 if reference_valid else 8),
            "status_text": "; ".join(status_parts) if status_parts else "OK",
            # LabOne sample flags are reported separately.  Reference LOCK is
            # determined by extrefs/0/locked plus the frequency comparison;
            # unrelated warning bits must not turn a valid PLL into WARNING.
            "reference_valid": reference_valid,
            "sensitivity_index": "",
            "input_range_v": input_range_v,
            "input_utilization": input_utilization,
            "auto_range": "",
        }

    def connect(
        self,
        source_resource: str,
        lockin_resources: dict[str, str],
    ) -> tuple[str, dict[str, str]]:
        """Compatibility helper used by workflows that connect a device set."""
        if not lockin_resources:
            raise ValueError("至少选择一台 SR830")
        source_was_connected = self.source_connected
        existing_keys = set(self.connected_lockin_keys)
        try:
            source_identity = self.connect_source(source_resource)
            for key, resource in lockin_resources.items():
                self.connect_lockin(key, resource)
            identities = {
                key: self.lockin_identities[key] for key in lockin_resources
            }
            return source_identity, identities
        except BaseException:
            for key in set(self.connected_lockin_keys) - existing_keys:
                try:
                    self.disconnect_lockin(key)
                except BaseException:
                    pass
            if not source_was_connected and self.source_connected:
                try:
                    self.disconnect_source()
                except BaseException:
                    pass
            raise

    def configure(
        self,
        initial_rms_ma: float,
        frequency_hz: float,
        compliance_v: float,
        lockin_configs: dict[str, dict],
        marker_line: int = NONLOCAL_MARKER_LINE,
        mfli_config: dict[str, object] | None = None,
        use_nanovoltmeter: bool = False,
        sample_hz: float = NONLOCAL_SAMPLE_HZ,
        output_mode: str = "AC",
    ) -> tuple[float, dict[str, dict]]:
        with self.lock:
            output_mode = str(output_mode).strip().upper()
            if output_mode not in {"AC", "DC"}:
                raise ValueError("6221 输出模式只能选择 AC 或 DC")
            if not self.connected:
                raise RuntimeError("Non-local IV 仪器尚未连接")
            if not set(lockin_configs).issubset(self.lockins):
                raise RuntimeError("锁相配置包含尚未连接的 SR830")
            if not lockin_configs and not mfli_config and not use_nanovoltmeter:
                raise RuntimeError("至少选择一台电压测量仪表")
            if mfli_config and not self.mfli_connected:
                raise RuntimeError("已选择 Zurich MFLI，但仪器尚未连接")
            if use_nanovoltmeter and self.nanovoltmeter is None:
                raise RuntimeError("已选择 2182A，但仪器尚未连接")
            if output_mode == "DC" and (lockin_configs or mfli_config):
                raise ValueError(
                    "6221 DC 输出没有锁相参考；DC 模式只能选择 2182A 直流测量"
                )
            if output_mode == "DC" and not use_nanovoltmeter:
                raise ValueError("6221 DC 输出模式必须选择 2182A 参与扫描")
            numeric = (
                initial_rms_ma,
                compliance_v,
                marker_line,
            )
            if not all(math.isfinite(float(value)) for value in numeric):
                raise ValueError("6221 参数必须是有限数值")
            if output_mode == "AC" and initial_rms_ma <= 0:
                raise ValueError("6221 AC RMS 电流必须大于 0 mA")
            if output_mode == "DC" and abs(initial_rms_ma) > 105.0:
                raise ValueError("6221 DC 电流必须在 ±105 mA 内")
            if output_mode == "AC" and not 1e-3 <= frequency_hz <= 1e5:
                raise ValueError("6221 波形频率必须在 0.001–100000 Hz 内")
            if not K6221_MIN_COMPLIANCE_V <= compliance_v <= K6221_MAX_COMPLIANCE_V:
                raise ValueError("6221 限压必须在 0.1–105 V 内")
            if not 1 <= int(marker_line) <= 6:
                raise ValueError("6221 Trigger Link 输出线必须在 1–6 内")
            peak_a = math.sqrt(2.0) * initial_rms_ma * 1e-3
            if output_mode == "AC" and peak_a > NONLOCAL_MAX_PEAK_A:
                raise ValueError(
                    "6221 正弦波峰值超过 105 mA；GUI 电流单位是 RMS"
                )
            for key, requested in lockin_configs.items():
                harmonic = int(requested["harmonic"])
                if not 1 <= harmonic <= 19999:
                    raise ValueError(f"SR830 #{key} 倍频必须在 1–19999 内")
                if frequency_hz * harmonic > 102000.0:
                    raise ValueError(
                        f"SR830 #{key} 解调频率超过 102 kHz"
                    )
            if mfli_config:
                mfli_harmonic = int(mfli_config["harmonic"])
                if mfli_harmonic < 1:
                    raise ValueError("MFLI 倍频必须是正整数")
                if frequency_hz * mfli_harmonic > 500000.0:
                    raise ValueError(
                        "MFLI 解调频率超过基础型号 500 kHz 限制"
                    )
            self.source.write("*RST")
            self.source.write("*CLS")
            if output_mode == "AC":
                commands = (
                    f"CURR:COMP {compliance_v:.12g}", "SOUR:WAVE:FUNC SIN",
                    f"SOUR:WAVE:FREQ {frequency_hz:.12g}",
                    f"SOUR:WAVE:AMPL {peak_a:.12e}", "SOUR:WAVE:OFFS 0",
                    "SOUR:WAVE:RANG BEST",
                    f"SOUR:WAVE:PMAR {NONLOCAL_MARKER_PHASE_DEG:g}",
                    f"SOUR:WAVE:PMAR:OLIN {marker_line}",
                    "SOUR:WAVE:PMAR:STAT ON", "OUTP OFF",
                )
            else:
                commands = (
                    f"CURR:COMP {compliance_v:.12g}",
                    "SOUR:CURR:RANG:AUTO ON",
                    "SOUR:CURR 0",
                    "OUTP OFF",
                )
            for command in commands:
                self._write_6221(command)
            actual_compliance = self._query_float(self.source, "CURR:COMP?")
            if not math.isclose(
                actual_compliance, compliance_v, rel_tol=5e-4, abs_tol=1e-6
            ):
                raise RuntimeError(
                    f"6221 限压回读不符：请求 {compliance_v:g} V，"
                    f"回读 {actual_compliance:g} V"
                )
            if output_mode == "AC":
                actual_frequency = self._query_float(
                    self.source, "SOUR:WAVE:FREQ?"
                )
                actual_peak = self._query_float(
                    self.source, "SOUR:WAVE:AMPL?"
                )
                actual_offset = self._query_float(
                    self.source, "SOUR:WAVE:OFFS?"
                )
                marker_enabled = int(self._query_float(
                    self.source, "SOUR:WAVE:PMAR:STAT?"
                ))
                actual_marker_line = int(self._query_float(
                    self.source, "SOUR:WAVE:PMAR:OLIN?"
                ))
                marker_phase = self._query_float(
                    self.source, "SOUR:WAVE:PMAR?"
                )
                if not math.isclose(
                    actual_frequency, frequency_hz,
                    rel_tol=5e-3, abs_tol=0.1,
                ):
                    raise RuntimeError(
                        f"6221 频率回读不符：请求 {frequency_hz:g} Hz，"
                        f"回读 {actual_frequency:g} Hz"
                    )
                if not math.isclose(
                    actual_peak, peak_a, rel_tol=5e-4, abs_tol=1e-12
                ):
                    raise RuntimeError(
                        f"6221 振幅回读不符：请求 {peak_a:g} Apeak，"
                        f"回读 {actual_peak:g} Apeak"
                    )
                if not math.isclose(actual_offset, 0.0, abs_tol=1e-12):
                    raise RuntimeError(
                        f"6221 波形偏置未归零：{actual_offset:g} A"
                    )
                if marker_enabled != 1 or actual_marker_line != int(marker_line):
                    raise RuntimeError(
                        "6221 Trigger Link 相位标记回读不符："
                        f"enabled={marker_enabled}, line={actual_marker_line}"
                    )
                if not math.isclose(
                    marker_phase, NONLOCAL_MARKER_PHASE_DEG, abs_tol=1e-6
                ):
                    raise RuntimeError(
                        f"6221 相位标记回读不符：{marker_phase:g}°"
                    )
            else:
                actual_frequency = math.nan
                auto_range = int(self._query_float(
                    self.source, "SOUR:CURR:RANG:AUTO?"
                ))
                actual_current = self._query_float(self.source, "SOUR:CURR?")
                output_state = int(self._query_float(self.source, "OUTP?"))
                if auto_range != 1 or not math.isclose(
                    actual_current, 0.0, abs_tol=1e-12
                ) or output_state != 0:
                    raise RuntimeError(
                        "6221 DC 初始化回读不符："
                        f"auto_range={auto_range}, current={actual_current:g} A, "
                        f"output={output_state}"
                    )

            self.source_output_mode = output_mode

            readbacks = {}
            for key in sorted(lockin_configs, key=int):
                lockin = self.lockins[key]
                requested = lockin_configs[key]
                harmonic = int(requested["harmonic"])
                coupling = str(requested["coupling"]).upper()
                coupling_code = 0 if coupling == "AC" else 1
                lockin.write("*CLS")
                for command in (
                    "FMOD 0", "RSLP 2", f"HARM {harmonic}", "ISRC 1",
                    "IGND 0", f"ICPL {coupling_code}", "ILIN 1", "SENS 9",
                    "OFLT 10", "OFSL 1", "RMOD 1", "PHAS 0",
                    "DDEF 1,1,0", "DDEF 2,1,0",
                ):
                    self._write_sr830(key, command)
                actual_harmonic = int(
                    self._query_sr830_numbers(key, "HARM?", 1)[0]
                )
                actual_coupling = int(
                    self._query_sr830_numbers(key, "ICPL?", 1)[0]
                )
                reference_mode = int(
                    self._query_sr830_numbers(key, "FMOD?", 1)[0]
                )
                reference_slope = int(
                    self._query_sr830_numbers(key, "RSLP?", 1)[0]
                )
                channel_1 = tuple(
                    int(value)
                    for value in self._query_sr830_numbers(key, "DDEF? 1", 2)
                )
                channel_2 = tuple(
                    int(value)
                    for value in self._query_sr830_numbers(key, "DDEF? 2", 2)
                )
                if actual_harmonic != harmonic or actual_coupling != coupling_code:
                    raise RuntimeError(
                        f"SR830 #{key} 配置回读不符：HARM={actual_harmonic}, "
                        f"ICPL={actual_coupling}"
                    )
                if reference_mode != 0 or reference_slope != 2:
                    raise RuntimeError(
                        f"SR830 #{key} 外部参考回读不符：FMOD={reference_mode}, "
                        f"RSLP={reference_slope}"
                    )
                if channel_1 != (1, 0) or channel_2 != (1, 0):
                    raise RuntimeError(
                        f"SR830 #{key} 前面板显示回读不符：CH1={channel_1}, CH2={channel_2}"
                    )
                sensitivity = int(
                    self._query_sr830_numbers(key, "SENS?", 1)[0]
                )
                self.sensitivity_indices[key] = sensitivity
                self.low_range_counts[key] = 0
                self.range_cooldowns[key] = 0
                readbacks[key] = {
                    "meter_type": "SR830",
                    "harmonic": actual_harmonic,
                    "coupling": "AC" if actual_coupling == 0 else "DC",
                    "channel": requested["channel"],
                    "resource": f"GPIB {key}",
                }
            if mfli_config:
                readbacks["mfli"] = self.configure_mfli(
                    str(mfli_config["coupling"]),
                    int(mfli_config["harmonic"]),
                    str(mfli_config["channel"]),
                    str(mfli_config["reference_source"]),
                    sample_rate_hz=sample_hz,
                    input_impedance=str(mfli_config["input_impedance"]),
                    input_scaling=float(mfli_config["input_scaling"]),
                )
            if use_nanovoltmeter:
                readbacks["2182"] = {
                    "meter_type": "2182A",
                    **self.configure_nanovoltmeter(channel=1, nplc=1.0),
                }
            return actual_frequency, readbacks

    def set_current(self, rms_ma: float, frequency_hz: float) -> float:
        with self.lock:
            if not math.isfinite(float(rms_ma)):
                raise ValueError("6221 电流必须是有限数值")
            if self.source_output_mode == "DC":
                if abs(float(rms_ma)) > 105.0:
                    raise ValueError("6221 DC 电流必须在 ±105 mA 内")
                requested_a = float(rms_ma) * 1e-3
                for command in (
                    f"SOUR:CURR {requested_a:.12e}",
                    "OUTP ON",
                ):
                    self._write_6221(command)
                output_state = int(self._query_float(self.source, "OUTP?"))
                readback_a = self._query_float(self.source, "SOUR:CURR?")
                if output_state != 1:
                    raise RuntimeError("6221 DC 输出未成功开启")
                if not math.isclose(
                    readback_a, requested_a, rel_tol=5e-4, abs_tol=1e-12
                ):
                    raise RuntimeError(
                        f"6221 DC 电流回读不符：{readback_a:g} A"
                    )
                self.output_enabled = True
                return readback_a * 1e3
            if float(rms_ma) <= 0:
                raise ValueError("6221 AC RMS 电流必须是有限正数")
            if not 1e-3 <= float(frequency_hz) <= 1e5:
                raise ValueError("6221 波形频率必须在 0.001–100000 Hz 内")
            peak_a = math.sqrt(2.0) * float(rms_ma) * 1e-3
            if peak_a > NONLOCAL_MAX_PEAK_A:
                raise ValueError("6221 正弦波峰值超过 105 mA")
            for command in (
                "SOUR:WAVE:ABOR",
                f"SOUR:WAVE:AMPL {peak_a:.12e}",
                "SOUR:WAVE:ARM",
                "SOUR:WAVE:INIT",
            ):
                self._write_6221(command)
            if int(self._query_float(self.source, "OUTP?")) != 1:
                raise RuntimeError("6221 正弦波未成功开启")
            actual_frequency = self._query_float(self.source, "SOUR:WAVE:FREQ?")
            if not math.isclose(actual_frequency, frequency_hz, rel_tol=5e-3, abs_tol=0.1):
                raise RuntimeError(
                    f"6221 频率回读不符：{actual_frequency:g} Hz"
                )
            self.output_enabled = True
            peak_readback = self._query_float(self.source, "SOUR:WAVE:AMPL?")
            if not math.isclose(peak_readback, peak_a, rel_tol=5e-4, abs_tol=1e-12):
                raise RuntimeError(
                    f"6221 电流振幅回读不符：{peak_readback:g} Apeak"
                )
            return peak_readback / math.sqrt(2.0) * 1e3

    def wait_references(
        self,
        frequency_hz: float,
        stop_event: threading.Event,
        lockin_keys: tuple[str, ...] | None = None,
    ) -> dict[str, dict]:
        keys = (
            tuple(lockin_keys)
            if lockin_keys is not None
            else self.connected_lockin_keys
        )
        results = {
            key: self._wait_reference_one(key, frequency_hz, stop_event)
            for key in keys
        }
        if self.mfli_connected and self.mfli_config:
            results["mfli"] = self._wait_mfli_reference(
                frequency_hz, stop_event
            )
        return results

    def _wait_mfli_reference(
        self, frequency_hz: float, stop_event: threading.Event
    ) -> dict:
        if self.mfli_initial_autorange_pending and not stop_event.is_set():
            with self.lock:
                action = self._run_mfli_autorange("initial")
            self.logger(f"Non-local MFLI 自动量程：{action}")
        deadline = time.monotonic() + 5.0
        last_sample = {
            "reference_valid": False,
            "reference_frequency_hz": math.nan,
            "status_text": (
                f"{self.mfli_config.get('reference_source', NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT)} "
                "外部参考未锁定"
            ),
        }
        while time.monotonic() < deadline and not stop_event.is_set():
            with self.lock:
                last_sample = self.read_mfli(frequency_hz)
            if last_sample["reference_valid"]:
                break
            stop_event.wait(0.1)
        return {
            "valid": bool(last_sample["reference_valid"]),
            "frequency_hz": float(last_sample["reference_frequency_hz"]),
            "status": int(last_sample["lia_status"]),
            "status_text": str(last_sample["status_text"]),
            "reference_source": str(
                self.mfli_config.get(
                    "reference_source",
                    NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT,
                )
            ),
        }

    def _wait_reference_one(
        self, key: str, frequency_hz: float, stop_event: threading.Event
    ) -> dict:
        deadline = time.monotonic() + 5.0
        last_frequency = math.nan
        last_status = 8
        while time.monotonic() < deadline and not stop_event.is_set():
            with self.lock:
                lockin = self.lockins[key]
                last_frequency = self._query_sr830_numbers(key, "FREQ?", 1)[0]
                last_status = int(
                    self._query_sr830_numbers(key, "LIAS?", 1)[0]
                )
            if not (last_status & 8) and math.isclose(
                last_frequency, frequency_hz, rel_tol=5e-3, abs_tol=0.1
            ):
                return {"valid": True, "frequency_hz": last_frequency, "status": last_status}
            stop_event.wait(0.1)
        return {"valid": False, "frequency_hz": last_frequency, "status": last_status}

    @staticmethod
    def _status_text(status: int) -> str:
        labels = []
        if status & 1:
            labels.append("输入/Reserve overload")
        if status & 2:
            labels.append("滤波器 overload")
        if status & 4:
            labels.append("输出 overload")
        if status & 8:
            labels.append("参考未锁定")
        return "; ".join(labels) if labels else "OK"

    def _run_mfli_autorange(self, reason: str) -> str:
        """Run the MFLI firmware autorange and verify its range readback."""
        if not self.mfli_connected:
            raise RuntimeError("Zurich MFLI 尚未连接")
        configured_old = float(self.mfli_config.get("input_range_v", math.nan))
        if self.mfli_bridge is not None:
            result = self.mfli_bridge.request("autorange")["autorange"]
            old_range = float(result["old_input_range_v"])
            new_range = float(result["input_range_v"])
        else:
            device = self.mfli_device
            range_node = f"/{device}/sigins/0/range"
            autorange_node = f"/{device}/sigins/0/autorange"
            old_range = float(self.mfli_daq.getDouble(range_node))
            self.mfli_daq.setInt(autorange_node, 1)
            deadline = time.monotonic() + 8.0
            while int(self.mfli_daq.getInt(autorange_node)) != 0:
                if time.monotonic() >= deadline:
                    raise RuntimeError("MFLI Signal Input 1 自动量程超时")
                time.sleep(0.02)
            self.mfli_daq.sync()
            new_range = float(self.mfli_daq.getDouble(range_node))
            for suffix in ("max", "min"):
                try:
                    self.mfli_daq.setDouble(
                        f"/{device}/sigins/0/{suffix}", 0.0
                    )
                except BaseException:
                    pass
        if not math.isfinite(old_range) or old_range <= 0:
            old_range = configured_old
        if not math.isfinite(new_range) or new_range <= 0:
            raise RuntimeError(f"MFLI 自动量程回读无效：{new_range!r}")
        self.mfli_config["input_range_v"] = new_range
        self.mfli_low_range_count = 0
        self.mfli_range_cooldown = 3
        self.mfli_initial_autorange_pending = False
        return f"RANGE {old_range:.6g}->{new_range:.6g} V ({reason})"

    def _auto_range_mfli(self, sample: dict[str, object]) -> str:
        """Continuously adapt Signal Input 1 using raw ADC utilization."""
        utilization = float(sample.get("input_utilization", 0.0))
        if not math.isfinite(utilization):
            return ""
        if utilization >= 0.85:
            return self._run_mfli_autorange("overload/high")
        if self.mfli_range_cooldown > 0:
            self.mfli_range_cooldown -= 1
            self.mfli_low_range_count = 0
            return ""
        if utilization < 0.15:
            self.mfli_low_range_count += 1
            if self.mfli_low_range_count >= 3:
                return self._run_mfli_autorange("low")
        else:
            self.mfli_low_range_count = 0
        return ""

    def _auto_range(self, key: str, r_v: float, status: int) -> str:
        old = self.sensitivity_indices[key]
        utilization = abs(r_v) / NONLOCAL_SR830_FULL_SCALE_V[old]
        requested = old
        reason = ""
        if status & 0x07 or utilization >= 0.85:
            requested = min(old + 1, len(NONLOCAL_SR830_FULL_SCALE_V) - 1)
            reason = "overload/high"
            self.low_range_counts[key] = 0
        elif self.range_cooldowns[key] > 0:
            self.range_cooldowns[key] -= 1
            self.low_range_counts[key] = 0
        elif utilization < 0.15 and old > 0:
            self.low_range_counts[key] += 1
            # Require several consecutive low readings; a single quiet sample
            # must not make sensitivity chatter during a sweep.
            if self.low_range_counts[key] >= 3:
                requested = old - 1
                reason = "low"
                self.low_range_counts[key] = 0
        else:
            self.low_range_counts[key] = 0
        if requested != old:
            self._write_sr830(key, f"SENS {requested}")
            actual = int(self._query_sr830_numbers(key, "SENS?", 1)[0])
            if actual != requested:
                raise RuntimeError(f"SR830 #{key} 自动量程回读不一致")
            self.sensitivity_indices[key] = actual
            self.range_cooldowns[key] = 3
            return f"SENS {old}->{actual} ({reason})"
        return ""

    def read_samples(
        self,
        expected_frequency_hz: float,
        measurement_keys: tuple[str, ...] | None = None,
    ) -> dict[str, dict]:
        with self.lock:
            keys = (
                tuple(measurement_keys)
                if measurement_keys is not None
                else self.connected_lockin_keys
            )
            output_on = int(self._query_float(self.source, "OUTP?")) == 1
            measurement_condition = int(
                self._query_float(self.source, "STAT:MEAS:COND?")
            )
            samples = {}
            for key in keys:
                if key == "2182":
                    voltage = self.read_nanovoltmeter()
                    samples[key] = {
                        "meter_type": "2182A",
                        "voltage": voltage,
                        "X": math.nan,
                        "Y": math.nan,
                        "R": voltage,
                        "phase_deg": math.nan,
                        "reference_frequency_hz": math.nan,
                        "lia_status": 0,
                        "status_text": "2182A DC sample (not AC lock-in)",
                        "reference_valid": True,
                        "measurement_valid": not bool(measurement_condition & 8),
                        "output_on": output_on,
                        "measurement_condition": measurement_condition,
                        "in_compliance": bool(measurement_condition & 8),
                        "sensitivity_index": "",
                        "auto_range": "",
                    }
                elif key == "mfli":
                    sample = self.read_mfli(expected_frequency_hz)
                    sample["auto_range"] = self._auto_range_mfli(sample)
                    sample.update(
                        output_on=output_on,
                        measurement_condition=measurement_condition,
                        in_compliance=bool(measurement_condition & 8),
                    )
                    sample["measurement_valid"] = bool(
                        sample["reference_valid"]
                        and not sample["lia_status"]
                        and not sample["in_compliance"]
                        and not sample["auto_range"]
                    )
                    samples[key] = sample
                else:
                    sample = self._read_sample_one(
                        key, expected_frequency_hz, output_on,
                        measurement_condition,
                    )
                    sample["meter_type"] = "SR830"
                    sample["voltage"] = sample["R"]
                    samples[key] = sample
            return samples

    def _read_sample_one(
        self, key: str, expected_frequency_hz: float,
        output_on: bool, measurement_condition: int,
    ) -> dict:
        lockin = self.lockins[key]
        values = self._query_sr830_numbers(key, "SNAP? 1,2,3,4,9", 5)
        status = int(self._query_sr830_numbers(key, "LIAS?", 1)[0])
        sensitivity_used = self.sensitivity_indices[key]
        auto_action = self._auto_range(key, values[2], status)
        reference_valid = not (status & 8) and math.isclose(
            values[4], expected_frequency_hz, rel_tol=5e-3, abs_tol=0.1
        )
        in_compliance = bool(measurement_condition & 8)
        return {
            "lockin_key": key,
            "X": values[0], "Y": values[1], "R": values[2],
            "phase_deg": values[3], "reference_frequency_hz": values[4],
            "lia_status": status, "status_text": self._status_text(status),
            "reference_valid": reference_valid, "output_on": output_on,
            "measurement_condition": measurement_condition,
            "in_compliance": in_compliance,
            # The reading that triggered a sensitivity change was acquired on
            # the old range and is intentionally excluded from point averages.
            "measurement_valid": bool(
                reference_valid
                and not (status & 0x07)
                and not in_compliance
                and not auto_action
            ),
            "sensitivity_index": sensitivity_used, "auto_range": auto_action,
        }

    def output_off(self) -> None:
        with self.lock:
            if self.source is None:
                return
            errors = []
            for command in ("SOUR:WAVE:ABOR", "CURR 0", "OUTP OFF"):
                try:
                    self.source.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            self.output_enabled = False
            if errors:
                raise RuntimeError("6221 输出关闭失败：" + "; ".join(errors))

    def confirm_output_off(self, context: str) -> None:
        """Verify the physical 6221 output before a VI pulse/resistance read."""
        with self.lock:
            if self.source is None:
                raise RuntimeError("6221尚未连接")
            output_state = int(round(self._query_float(self.source, "OUTP?")))
            if output_state != 0 or self.output_enabled:
                self.output_off()
                output_state = int(round(self._query_float(self.source, "OUTP?")))
            if output_state != 0:
                raise RuntimeError(
                    f"{context}时6221输出仍为ON；禁止Keithley 2410动作"
                )

    def disconnect(self) -> None:
        with self.lock:
            source, manager = self.source, self.resource_manager
            lockins = list(self.lockins.values())
            source_resource = self.source_resource
            lockin_resources = tuple(self.lockin_resources.values())
            nanovoltmeter_resource = self.nanovoltmeter_resource
            mfli_lease_resource = self.mfli_lease_resource
            mfli_daq = self.mfli_daq
            mfli_bridge = self.mfli_bridge
            nanovoltmeter = self.nanovoltmeter
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            for instrument in lockins + [nanovoltmeter, source]:
                if instrument is not None:
                    try:
                        instrument.write("*CLS")
                        instrument.close()
                    except BaseException:
                        pass
            if mfli_daq is not None:
                try:
                    mfli_daq.setInt(
                        f"/{self.mfli_device}/extrefs/"
                        f"{NONLOCAL_MFLI_EXTREF_CHANNEL}/enable",
                        0,
                    )
                    mfli_daq.setInt(
                        f"/{self.mfli_device}/demods/"
                        f"{NONLOCAL_MFLI_DEMODULATOR}/enable",
                        0,
                    )
                    mfli_daq.setInt(
                        f"/{self.mfli_device}/demods/"
                        f"{NONLOCAL_MFLI_EXTREF_DEMODULATOR}/enable",
                        0,
                    )
                    mfli_daq.sync()
                except BaseException:
                    pass
                try:
                    mfli_daq.disconnect()
                except BaseException:
                    pass
            if mfli_bridge is not None:
                try:
                    mfli_bridge.close()
                except BaseException:
                    mfli_bridge.close(force=True)
            if manager is not None:
                try:
                    manager.close()
                except BaseException:
                    pass
            self.source = self.nanovoltmeter = self.resource_manager = None
            self.mfli_daq = None
            self.mfli_bridge = None
            self.mfli_device = ""
            self.mfli_props = {}
            self.mfli_config = {}
            self.mfli_identity = ""
            self.lockins = {}
            self.source_identity = ""
            self.lockin_identities = {}
            self.source_resource = ""
            self.lockin_resources = {}
            self.nanovoltmeter_resource = ""
            self.mfli_lease_resource = ""
            self.nanovoltmeter_identity = ""
            self.sensitivity_indices = {}
            self.low_range_counts = {}
            self.range_cooldowns = {}
            self.mfli_low_range_count = 0
            self.mfli_range_cooldown = 0
            self.mfli_initial_autorange_pending = False
            self.output_enabled = False
            self.source_output_mode = "AC"
            release_instrument_lease(source_resource, self)
            for resource in lockin_resources:
                release_instrument_lease(resource, self)
            release_instrument_lease(nanovoltmeter_resource, self)
            release_instrument_lease(mfli_lease_resource, self)
            self.logger("Non-local IV 已停止 6221 输出并断开全部仪表")
            if shutdown_error is not None:
                raise shutdown_error

    def disconnect_source(self) -> None:
        """Safely stop and close only the 6221."""
        with self.lock:
            source = self.source
            resource = self.source_resource
            if source is None:
                self.source_resource = ""
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            try:
                source.write("*CLS")
            except BaseException:
                pass
            try:
                source.close()
            except BaseException:
                pass
            self.source = None
            self.source_identity = ""
            self.source_resource = ""
            self.source_output_mode = "AC"
            self.output_enabled = False
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger("Non-local IV 6221 已停止输出并断开")
            if shutdown_error is not None:
                raise shutdown_error

    def disconnect_lockin(self, key: str) -> None:
        """Close one SR830 while preserving all other connected devices."""
        key = str(key)
        with self.lock:
            lockin = self.lockins.pop(key, None)
            resource = self.lockin_resources.pop(key, "")
            if lockin is None:
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            try:
                lockin.write("*CLS")
            except BaseException:
                pass
            try:
                lockin.close()
            except BaseException:
                pass
            self.lockin_identities.pop(key, None)
            self.sensitivity_indices.pop(key, None)
            self.low_range_counts.pop(key, None)
            self.range_cooldowns.pop(key, None)
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger(f"Non-local IV SR830 #{key} 已断开")

    def disconnect_nanovoltmeter(self) -> None:
        """Close only the optional Keithley 2182A."""
        with self.lock:
            meter = self.nanovoltmeter
            resource = self.nanovoltmeter_resource
            if meter is None:
                self.nanovoltmeter_resource = ""
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            try:
                meter.write("*CLS")
            except BaseException:
                pass
            try:
                meter.close()
            except BaseException:
                pass
            self.nanovoltmeter = None
            self.nanovoltmeter_identity = ""
            self.nanovoltmeter_resource = ""
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger("Non-local IV Keithley 2182A 已断开")

    def disconnect_mfli(self) -> None:
        """Disable streaming and close only the Zurich LabOne session."""
        with self.lock:
            daq = self.mfli_daq
            bridge = self.mfli_bridge
            mfli_lease_resource = self.mfli_lease_resource
            if daq is None and bridge is None:
                self.mfli_lease_resource = ""
                release_instrument_lease(mfli_lease_resource, self)
                self._close_manager_if_unused()
                return
            if daq is not None:
                extref_demod = int(
                    self.mfli_config.get(
                        "extref_demodulator", NONLOCAL_MFLI_DEMODULATOR
                    )
                )
                disable_nodes = [
                    f"/{self.mfli_device}/extrefs/"
                    f"{NONLOCAL_MFLI_EXTREF_CHANNEL}/enable",
                    f"/{self.mfli_device}/demods/"
                    f"{NONLOCAL_MFLI_DEMODULATOR}/enable",
                ]
                if extref_demod != NONLOCAL_MFLI_DEMODULATOR:
                    disable_nodes.append(
                        f"/{self.mfli_device}/demods/{extref_demod}/enable"
                    )
                for node in disable_nodes:
                    try:
                        daq.setInt(node, 0)
                    except BaseException:
                        pass
                try:
                    daq.sync()
                except BaseException:
                    pass
            try:
                if daq is not None:
                    daq.disconnect()
            except BaseException:
                pass
            if bridge is not None:
                try:
                    bridge.close()
                except BaseException:
                    bridge.close(force=True)
            self.mfli_daq = None
            self.mfli_bridge = None
            self.mfli_device = ""
            self.mfli_props = {}
            self.mfli_config = {}
            self.mfli_identity = ""
            self.mfli_lease_resource = ""
            self.mfli_low_range_count = 0
            self.mfli_range_cooldown = 0
            self.mfli_initial_autorange_pending = False
            release_instrument_lease(mfli_lease_resource, self)
            self._close_manager_if_unused()
            self.logger("Non-local Zurich MFLI 已断开")


class MagnetProtocolError(RuntimeError):
    """A magnet device replied without the expected value."""


class MagnetAsciiSerialDevice:
    """Thread-safe CR-command/LF-reply serial transport for the MOKE magnets."""

    def __init__(
        self,
        port: str,
        label: str,
        logger: Callable[[str], None],
    ) -> None:
        self.port = port
        self.label = label
        self.logger = logger
        self.handle = None
        self.lock = threading.RLock()

    @property
    def connected(self) -> bool:
        return bool(self.handle is not None and self.handle.is_open)

    def _log(self, text: str) -> None:
        self.logger(f"{self.label}: {text}")

    def connect(self) -> None:
        if serial is None:
            raise RuntimeError("缺少 pyserial；请运行：py -m pip install pyserial")
        with self.lock:
            self.close()
            self.handle = serial.Serial(
                port=self.port,
                baudrate=MAGNET_BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=MAGNET_READ_TIMEOUT_S,
                write_timeout=MAGNET_WRITE_TIMEOUT_S,
                xonxoff=False,
                rtscts=False,
                dsrdtr=False,
            )
            self.handle.reset_input_buffer()
            self.handle.reset_output_buffer()
            self._log(f"已打开 {self.port} (115200 / 8N1)")

    def close(self) -> None:
        with self.lock:
            handle = self.handle
            self.handle = None
            if handle is not None:
                try:
                    if handle.is_open:
                        handle.close()
                finally:
                    self._log(f"已关闭 {self.port}")

    def _require_open(self):
        if not self.connected:
            raise RuntimeError(f"{self.label} 尚未连接")
        return self.handle

    @staticmethod
    def _decode(raw: bytes) -> str:
        return raw.decode("ascii", errors="replace").strip("\x00\r\n ")

    def exchange(
        self,
        command: str,
        matcher: Callable[[str], object | None] | None = None,
        deadline_s: float = MAGNET_REPLY_DEADLINE_S,
        attempts: int = 1,
    ):
        wire = command.rstrip("\r\n").encode("ascii") + b"\r"
        with self.lock:
            handle = self._require_open()
            all_received: list[str] = []
            attempts = max(1, int(attempts))
            for attempt in range(1, attempts + 1):
                if attempt > 1:
                    self._log(f"第 {attempt}/{attempts} 次尝试 {command!r}")
                    time.sleep(MAGNET_RETRY_DELAY_S)
                # Flush stale bytes only before the first transmission.  A
                # slow BOP reply can arrive just after the first deadline; do
                # not discard that valid late reply before a retry.
                if attempt == 1:
                    handle.reset_input_buffer()
                handle.write(wire)
                handle.flush()
                self._log(f"TX {wire!r}")
                if matcher is None:
                    self._drain_quiet(handle)
                    return None

                result, received = self._read_matching_reply(
                    handle, matcher, deadline_s
                )
                all_received.extend(received)
                if result is not None:
                    return result

            summary = " | ".join(all_received) if all_received else "<无响应>"
            raise MagnetProtocolError(
                f"{self.label} 连续 {attempts} 次未返回预期数据；收到：{summary}"
            )

    def _read_matching_reply(
        self,
        handle,
        matcher: Callable[[str], object | None],
        deadline_s: float,
    ) -> tuple[object | None, list[str]]:
        """Accumulate fragmented serial bytes before parsing reply lines."""
        deadline = time.monotonic() + deadline_s
        pending = bytearray()
        received: list[str] = []

        def consume(raw: bytes):
            text = self._decode(raw)
            if not text:
                return None
            received.append(text)
            self._log(f"RX {raw!r}")
            return matcher(text)

        while time.monotonic() < deadline:
            waiting = int(getattr(handle, "in_waiting", 0) or 0)
            chunk = handle.read(waiting if waiting > 0 else 1)
            if not chunk:
                continue
            pending.extend(chunk)

            # Replies normally end in CR/LF.  Splitting on either delimiter also
            # handles adapters that deliver CR and LF in separate USB packets.
            while True:
                delimiter_indexes = [
                    index
                    for index in (pending.find(b"\r"), pending.find(b"\n"))
                    if index >= 0
                ]
                if not delimiter_indexes:
                    break
                index = min(delimiter_indexes)
                raw = bytes(pending[:index])
                del pending[: index + 1]
                result = consume(raw)
                if result is not None:
                    return result, received

            # The captured devices normally terminate replies, but accepting a
            # complete value before the terminator makes USB packet timing less
            # fragile without accepting arbitrary partial text.
            if pending:
                text = self._decode(bytes(pending))
                result = matcher(text) if text else None
                if result is not None:
                    received.append(text)
                    self._log(f"RX {bytes(pending)!r}")
                    return result, received

        if pending:
            consume(bytes(pending))
        return None, received

    def _drain_quiet(self, handle) -> None:
        end = time.monotonic() + MAGNET_QUIET_TIME_S
        while time.monotonic() < end:
            if handle.in_waiting <= 0:
                time.sleep(0.005)
                continue
            raw = handle.read_until(b"\n")
            if raw:
                text = self._decode(raw)
                if text:
                    self._log(f"RX {raw!r}")
                end = time.monotonic() + MAGNET_QUIET_TIME_S


class MagnetKepcoBOP(MagnetAsciiSerialDevice):
    def __init__(
        self,
        port: str,
        label: str,
        logger: Callable[[str], None],
    ) -> None:
        super().__init__(port, label, logger)
        self.output_armed = False

    def connect(self) -> None:
        super().connect()
        self.output_armed = False

    def close(self) -> None:
        self.output_armed = False
        super().close()

    @staticmethod
    def _parse_current(line: str) -> float | None:
        cleaned = MAGNET_CHECKSUM_RE.sub("", line)
        match = MAGNET_CURRENT_RE.search(cleaned)
        return float(match.group(1)) if match else None

    def set_current(self, amperes: float) -> None:
        value = float(amperes)
        if not math.isfinite(value):
            raise ValueError("磁体电流必须是有限数值")
        if abs(value) > MAGNET_CURRENT_LIMIT_A + 1e-12:
            raise ValueError(
                f"电流 {value:g} A 超过软件限值 ±{MAGNET_CURRENT_LIMIT_A:g} A"
            )
        if value != 0.0 and not self.output_armed:
            raise RuntimeError(
                f"{self.label} 尚未使能；请先点击“使能/归零”"
            )
        # NI I/O Trace writes T and then drains the echo/prompt; it does not
        # require a particular ``-->`` line before moving on.  Some BOPs emit
        # only an echo, some emit a delayed prompt, and requiring that prompt
        # caused needless retransmission and eventually desynchronised IQ.
        # The following IQ readback is the authoritative verification.
        self.exchange(f"T {value:.3f}")

    def query_current(self) -> float:
        return float(
            self.exchange(
                "IQ", self._parse_current, attempts=MAGNET_QUERY_ATTEMPTS
            )
        )

    def prepare_remote(self) -> None:
        """Wake the BOP into remote mode without enabling its output."""
        self.output_armed = False
        # As in the captured LabVIEW sequence, remote/en/T are write-only
        # commands.  Their echoes/prompts are drained, while IQ verifies the
        # resulting state after the complete handshake.
        self.exchange("remote")
        time.sleep(MAGNET_REMOTE_SETTLE_S)

    def initialize_at_zero(self) -> float:
        # Send zero before and after enable to reduce retained-setpoint risk.
        self.output_armed = False
        self.prepare_remote()
        self.set_current(0.0)
        self.exchange("en")
        self.output_armed = True
        self.set_current(0.0)
        time.sleep(MAGNET_COMMAND_SETTLE_S)
        return self.query_current()


class MagnetGaussMeter(MagnetAsciiSerialDevice):
    @staticmethod
    def _parse_field(line: str) -> float | None:
        match = MAGNET_FIELD_RE.search(line)
        return float(match.group(1)) if match else None

    def query_field(self) -> float:
        return float(
            self.exchange(
                "GS", self._parse_field, attempts=MAGNET_QUERY_ATTEMPTS
            )
        )


@dataclass
class MagnetChannel:
    key: str
    bop: MagnetKepcoBOP | None = None
    gauss: MagnetGaussMeter | None = None

    def close(self) -> None:
        if self.bop is not None:
            self.bop.close()
        if self.gauss is not None:
            self.gauss.close()
        self.bop = None
        self.gauss = None


class K10CR1KinesisController:
    """Self-contained Kinesis controller for a Thorlabs K10CR1 stage.

    Kinesis is loaded only when Connect is pressed, so this combined program
    still starts normally on a computer without pythonnet or Kinesis.
    """

    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.device = None
        self.configuration = None
        self.serial_no = K10CR1_DEFAULT_SERIAL
        self._connection_lock = threading.RLock()
        self._api_loaded = False
        self._DeviceManagerCLI = None
        self._DeviceConfiguration = None
        self._CageRotator = None
        self._Decimal = None
        self._Convert = None
        self._MotorDirection = None

    @property
    def connected(self) -> bool:
        return self.device is not None

    def _log(self, text: str) -> None:
        self.logger(f"旋转台：{text}")

    @staticmethod
    def _kinesis_directory() -> Path:
        for directory in K10CR1_KINESIS_DIRECTORIES:
            if all((directory / dll).is_file() for dll in K10CR1_REQUIRED_DLLS):
                return directory
        checked = "\n".join(str(path) for path in K10CR1_KINESIS_DIRECTORIES)
        raise RuntimeError(
            "未找到完整的 Thorlabs Kinesis 安装。已检查：\n"
            f"{checked}\n请安装与 Python 位数一致的 Kinesis。"
        )

    def _load_api(self) -> None:
        if self._api_loaded:
            return
        if sys.platform != "win32":
            raise RuntimeError("Thorlabs Kinesis 控制只能在安装了 Kinesis 的 Windows 上运行")
        directory = self._kinesis_directory()
        try:
            import clr
        except ImportError as error:
            raise RuntimeError(
                "缺少 pythonnet；请在控制电脑运行：py -m pip install pythonnet"
            ) from error
        try:
            for filename in K10CR1_REQUIRED_DLLS:
                clr.AddReference(str(directory / filename))
            from System import Convert, Decimal
            from Thorlabs.MotionControl.DeviceManagerCLI import (
                DeviceConfiguration,
                DeviceManagerCLI,
            )
            from Thorlabs.MotionControl.GenericMotorCLI import MotorDirection
            from Thorlabs.MotionControl.IntegratedStepperMotorsCLI import CageRotator
        except BaseException as error:
            raise RuntimeError(f"Kinesis DLL 加载失败：{error}") from error
        self._Decimal = Decimal
        self._DeviceManagerCLI = DeviceManagerCLI
        self._DeviceConfiguration = DeviceConfiguration
        self._CageRotator = CageRotator
        self._api_loaded = True
        self._Convert = Convert
        self._MotorDirection = MotorDirection
        self._log(f"已加载 Kinesis：{directory}")

    @staticmethod
    def _flag(status, name: str) -> bool:
        try:
            return bool(getattr(status, name))
        except BaseException:
            return False

    @staticmethod
    def _text(value) -> str:
        try:
            return str(value)
        except BaseException:
            return ""

    def _require_device(self):
        if self.device is None:
            raise RuntimeError("K10CR1 旋转台尚未连接")
        return self.device

    def connect(self, serial_no: str) -> dict[str, object]:
        serial_no = serial_no.strip()
        if not serial_no.isdigit():
            raise ValueError("旋转台 S/N 必须只包含数字")
        with self._connection_lock:
            if self.device is not None:
                if serial_no == self.serial_no:
                    return self.read_state()
                self.disconnect()
            self._load_api()
            self._DeviceManagerCLI.BuildDeviceList()
            devices = [str(item) for item in self._DeviceManagerCLI.GetDeviceList()]
            if serial_no not in devices:
                shown = ", ".join(devices) if devices else "未发现任何 Kinesis 设备"
                raise RuntimeError(f"未发现 S/N {serial_no}；设备列表：{shown}")

            device = self._CageRotator.CreateCageRotator(serial_no)
            if device is None:
                raise RuntimeError(f"Kinesis 无法创建 S/N {serial_no} 的 CageRotator")
            self.device = device
            self.serial_no = serial_no
            polling_started = False
            try:
                device.Connect(serial_no)
                if not bool(device.IsSettingsInitialized()):
                    device.WaitForSettingsInitialized(15_000)
                if not bool(device.IsSettingsInitialized()):
                    raise TimeoutError("等待 K10CR1 设置初始化超时")
                device.StartPolling(250)
                polling_started = True
                time.sleep(0.5)
                device.EnableDevice()
                time.sleep(1.0)
                self.configuration = device.LoadMotorConfiguration(
                    serial_no,
                    self._DeviceConfiguration.DeviceSettingsUseOptionType.UseFileSettings,
                )
                if self.configuration is None:
                    raise RuntimeError("LoadMotorConfiguration 返回空配置")
                settings_name = self._text(
                    getattr(self.configuration, "DeviceSettingsName", "")
                )
                description = self._text(getattr(device.GetDeviceInfo(), "Description", ""))
                identity = f"{description} {settings_name}".lower()
                if "k10cr" not in identity and "rotation" not in identity:
                    raise RuntimeError(
                        "载入的设备设置不像 K10CR1，拒绝运动："
                        f"Description={description!r}, Settings={settings_name!r}"
                    )
                self._log(
                    f"已连接 S/N {serial_no}；{description or 'K10CR1'}；"
                    f"设置 {settings_name or '已载入'}"
                )
                return self.read_state()
            except BaseException as error:
                try:
                    if polling_started:
                        device.StopPolling()
                except BaseException:
                    pass
                try:
                    device.Disconnect()
                except BaseException:
                    pass
                self.device = None
                self.configuration = None
                raise RuntimeError(
                    "K10CR1 连接或初始化失败。请确认 USB/电源正常，并先关闭 "
                    f"Thorlabs Kinesis 官方 GUI。原始错误：{error}"
                ) from error

    def disconnect(self) -> None:
        with self._connection_lock:
            device = self.device
            self.device = None
            self.configuration = None
            if device is None:
                return
            try:
                status = device.Status
                if (
                    self._flag(status, "IsMoving")
                    or self._flag(status, "IsHoming")
                    or self._flag(status, "IsJogging")
                ):
                    device.StopImmediate()
                    time.sleep(0.1)
            except BaseException:
                pass
            try:
                device.StopPolling()
            except BaseException:
                pass
            try:
                device.Disconnect()
            finally:
                self._log(f"已断开 S/N {self.serial_no}")

    def read_state(self) -> dict[str, object]:
        device = self._require_device()
        try:
            device.RequestStatus()
            time.sleep(0.1)
        except BaseException:
            pass
        status = device.Status
        info = device.GetDeviceInfo()
        return {
            "serial": self.serial_no,
            "description": self._text(getattr(info, "Description", "K10CR1")),
            "settings": self._text(
                getattr(self.configuration, "DeviceSettingsName", "")
            ),
            "position": float(self._Convert.ToDouble(device.Position)),
            "homed": self._flag(status, "IsHomed"),
            "homing": self._flag(status, "IsHoming"),
            "moving": self._flag(status, "IsMoving"),
            "jogging": self._flag(status, "IsJogging"),
            "enabled": self._flag(status, "IsEnabled"),
            "error": self._flag(status, "IsError"),
            "forward_limit": self._flag(status, "ForwardLimit"),
            "reverse_limit": self._flag(status, "ReverseLimit"),
        }

    def _run_motion(self, name: str, operation: Callable[[], None]) -> dict[str, object]:
        device = self._require_device()
        try:
            operation()
            state = self.read_state()
            self._log(f"{name}完成；位置 {float(state['position']):.6f}°")
            return state
        except BaseException as error:
            try:
                device.StopImmediate()
            except BaseException:
                pass
            raise RuntimeError(f"{name}失败：{error}") from error

    def home(self, timeout_ms: int = 120_000) -> dict[str, object]:
        device = self._require_device()
        state = self.read_state()
        if bool(state["forward_limit"]) and bool(state["reverse_limit"]):
            raise RuntimeError("正反限位同时触发；拒绝 Home，请检查传感器或 Kinesis 配置")
        self._log("开始 Home；旋转台可能进行较大角度运动")
        state = self._run_motion("Home", lambda: device.Home(int(timeout_ms)))
        time.sleep(0.25)
        state = self.read_state()
        if not bool(state["homed"]):
            raise RuntimeError("Home 命令返回后 IsHomed 仍为 False")
        return state

    def _move_relative_impl(
        self, angle_deg: float, timeout_ms: int, require_homed: bool
    ) -> dict[str, object]:
        state = self.read_state()
        if require_homed and not bool(state["homed"]):
            raise RuntimeError("设备尚未 Home；相对运动已禁止。请先 Home 或仅使用 ±1° 诊断微动")
        angle = float(angle_deg)
        if not math.isfinite(angle) or abs(angle) > 360.0:
            raise ValueError("相对角度必须在 -360° 至 +360° 内")
        if abs(angle) < 1e-12:
            self._log("相对角度为 0，未发送运动命令")
            return state
        direction = (
            self._MotorDirection.Forward
            if angle > 0.0
            else self._MotorDirection.Backward
        )
        device = self._require_device()
        return self._run_motion(
            f"相对转动 {angle:+g}°",
            lambda: device.MoveRelative(
                direction, self._Decimal(float(abs(angle))), int(timeout_ms)
            ),
        )

    def move_relative(self, angle_deg: float, timeout_ms: int = 120_000) -> dict[str, object]:
        return self._move_relative_impl(angle_deg, timeout_ms, require_homed=True)

    def move_absolute(self, angle_deg: float, timeout_ms: int = 120_000) -> dict[str, object]:
        state = self.read_state()
        if not bool(state["homed"]):
            raise RuntimeError("设备尚未 Home；绝对运动已禁止")
        angle = float(angle_deg)
        if not math.isfinite(angle) or angle < 0.0 or angle > 360.0:
            raise ValueError("绝对角度必须在 0° 至 360° 内")
        device = self._require_device()
        return self._run_motion(
            f"转到 {angle:g}°",
            lambda: device.MoveTo(self._Decimal(float(angle)), int(timeout_ms)),
        )

    def diagnostic_nudge(self, angle_deg: float, timeout_ms: int = 30_000) -> dict[str, object]:
        angle = float(angle_deg)
        if not math.isfinite(angle) or angle == 0.0 or abs(angle) > 1.0:
            raise ValueError("诊断微动必须非零且不超过 ±1°")
        return self._move_relative_impl(angle, timeout_ms, require_homed=False)

    def identify(self) -> None:
        self._require_device().IdentifyDevice()
        self._log("已发送设备识别指令")

    def stop(self) -> dict[str, object]:
        device = self._require_device()
        try:
            device.StopImmediate()
        except BaseException as first_error:
            try:
                device.Stop(5_000)
            except BaseException as second_error:
                raise RuntimeError(
                    f"StopImmediate 失败：{first_error}；Stop 也失败：{second_error}"
                ) from second_error
        time.sleep(0.1)
        self._log("已发送立即停止")
        return self.read_state()


class LEDProtocolError(RuntimeError):
    pass


@dataclass
class ChannelSettings:
    current: int = 0
    mode: int = 0
    p: int = 5
    g: int = 0
    d: int = 5
    f: int = 0

    def values(self) -> dict[str, int]:
        return {
            "i": self.current,
            "m": self.mode,
            "p": self.p,
            "g": self.g,
            "d": self.d,
            "f": self.f,
        }


class LEDSerialController:
    """Thread-safe implementation of the recovered COM5 protocol."""

    def __init__(self, logger: Callable[[str], None]) -> None:
        self._serial = None
        self._lock = threading.RLock()
        self._logger = logger

    @property
    def is_connected(self) -> bool:
        return self._serial is not None and self._serial.is_open

    @property
    def port(self) -> str | None:
        return None if self._serial is None else self._serial.port

    def connect(self, port: str) -> None:
        if serial is None:
            raise RuntimeError("缺少 pyserial：py -m pip install pyserial")
        port = port.strip()
        if not port:
            raise ValueError("串口名称不能为空")

        with self._lock:
            self.disconnect()
            connection = serial.Serial()
            connection.port = port
            connection.baudrate = BAUD_RATE
            connection.bytesize = serial.EIGHTBITS
            connection.parity = serial.PARITY_NONE
            connection.stopbits = serial.STOPBITS_ONE
            connection.timeout = READ_TIMEOUT_S
            connection.write_timeout = WRITE_TIMEOUT_S
            connection.xonxoff = False
            connection.rtscts = False
            connection.dsrdtr = False
            connection.dtr = False
            connection.rts = False
            try:
                connection.open()
                connection.reset_input_buffer()
                connection.reset_output_buffer()
            except BaseException:
                if connection.is_open:
                    connection.close()
                raise
            self._serial = connection
        self._logger(f"已连接 {port}: {BAUD_RATE}, 8-N-1")

    def disconnect(self) -> None:
        with self._lock:
            connection = self._serial
            self._serial = None
            if connection is not None and connection.is_open:
                port = connection.port
                connection.close()
                self._logger(f"已断开 {port}")

    def _connection(self):
        if not self.is_connected:
            raise RuntimeError("LED 控制器尚未连接")
        return self._serial

    @staticmethod
    def _command(parameter: str, channel: int, value: int | str) -> str:
        command = f"{parameter}{channel}={value}"
        if COMMAND_RE.fullmatch(command) is None:
            raise ValueError(f"非法 LED 指令：{command!r}")
        return command

    def _write_locked(self, command: str) -> None:
        connection = self._connection()
        payload = (command + "\r").encode("ascii")
        connection.write(payload)
        connection.flush()
        self._logger(f"TX  {command}\\r")
        time.sleep(COMMAND_DELAY_S)

    def query_parameter(self, parameter: str, channel: int) -> int:
        expected = f"{parameter}{channel}"
        with self._lock:
            connection = self._connection()
            connection.reset_input_buffer()
            self._write_locked(self._command(parameter, channel, "?"))
            response_bytes = connection.read_until(b"\n")

        if not response_bytes:
            raise TimeoutError(f"查询 {expected} 超时")
        try:
            response = response_bytes.decode("ascii").strip("\r\n")
        except UnicodeDecodeError as error:
            raise LEDProtocolError(f"收到非 ASCII 数据：{response_bytes!r}") from error
        self._logger(f"RX  {response_bytes!r}")
        match = RESPONSE_RE.fullmatch(response)
        if match is None:
            raise LEDProtocolError(f"无法识别的响应：{response!r}")
        returned = f"{match.group(1)}{match.group(2)}"
        if returned != expected:
            raise LEDProtocolError(f"查询 {expected}，控制器返回 {returned}")
        return int(match.group(3))

    def query_channel(self, channel: int) -> ChannelSettings:
        values = {
            parameter: self.query_parameter(parameter, channel)
            for parameter in PARAMETERS
        }
        return ChannelSettings(
            current=values["i"],
            mode=values["m"],
            p=values["p"],
            g=values["g"],
            d=values["d"],
            f=values["f"],
        )

    def query_all(self) -> dict[int, ChannelSettings]:
        return {channel: self.query_channel(channel) for channel in CHANNELS}

    def apply_channel(self, channel: int, settings: ChannelSettings) -> None:
        with self._lock:
            for parameter, value in settings.values().items():
                self._write_locked(self._command(parameter, channel, value))

    def apply_all(self, settings: dict[int, ChannelSettings]) -> None:
        with self._lock:
            for channel in CHANNELS:
                for parameter, value in settings[channel].values().items():
                    self._write_locked(self._command(parameter, channel, value))

    def all_off(self) -> None:
        with self._lock:
            for channel in CHANNELS:
                self._write_locked(self._command("i", channel, 0))
            for channel in CHANNELS:
                self._write_locked(self._command("m", channel, 0))


class CameraViewport:
    """Zoom/pan state and rendering copied from the standalone camera tool."""

    def __init__(self) -> None:
        self.zoom = 1.0
        self.center_x = None
        self.center_y = None
        self.image_shape = None
        self.mapping = None
        self.is_panning = False
        self.pan_start_x = 0
        self.pan_start_y = 0
        self.pan_center_x = 0.0
        self.pan_center_y = 0.0
        self.pan_scale_x = 1.0
        self.pan_scale_y = 1.0

    @staticmethod
    def auto_preview(image_u16, bounds=None):
        low, high = auto_contrast_limits(image_u16, bounds)
        return CameraViewport.fixed_preview(image_u16, low, high)

    @staticmethod
    def fixed_preview(image_u16, low: float, high: float):
        preview = np.clip(
            (image_u16.astype(np.float32) - low)
            * 255.0
            / max(high - low, 1.0),
            0,
            255,
        )
        return preview.astype(np.uint8)

    def crop_bounds(self, width: int, height: int) -> tuple[int, int, int, int]:
        if self.center_x is None:
            self.center_x = width / 2.0
        if self.center_y is None:
            self.center_y = height / 2.0

        crop_width = max(1, int(width / self.zoom))
        crop_height = max(1, int(height / self.zoom))
        self.center_x = float(
            np.clip(self.center_x, crop_width / 2.0, width - crop_width / 2.0)
        )
        self.center_y = float(
            np.clip(self.center_y, crop_height / 2.0, height - crop_height / 2.0)
        )
        x1 = int(round(self.center_x - crop_width / 2.0))
        y1 = int(round(self.center_y - crop_height / 2.0))
        x1 = int(np.clip(x1, 0, width - crop_width))
        y1 = int(np.clip(y1, 0, height - crop_height))
        return x1, y1, x1 + crop_width, y1 + crop_height

    def render(self, image, window_width: int, window_height: int):
        height, width = image.shape[:2]
        x1, y1, x2, y2 = self.crop_bounds(width, height)
        cropped = image[y1:y2, x1:x2]
        scale = min(
            window_width / cropped.shape[1], window_height / cropped.shape[0]
        )
        display_width = max(1, int(cropped.shape[1] * scale))
        display_height = max(1, int(cropped.shape[0] * scale))
        resized = cv2.resize(
            cropped,
            (display_width, display_height),
            interpolation=cv2.INTER_LINEAR,
        )
        canvas = np.zeros((window_height, window_width), dtype=np.uint8)
        offset_x = (window_width - display_width) // 2
        offset_y = (window_height - display_height) // 2
        canvas[
            offset_y : offset_y + display_height,
            offset_x : offset_x + display_width,
        ] = resized
        self.mapping = {
            "crop_x1": x1,
            "crop_y1": y1,
            "crop_width": x2 - x1,
            "crop_height": y2 - y1,
            "offset_x": offset_x,
            "offset_y": offset_y,
            "display_width": display_width,
            "display_height": display_height,
        }
        return canvas

    def _update_pan(self, mouse_x: int, mouse_y: int) -> None:
        self.center_x = self.pan_center_x - (
            mouse_x - self.pan_start_x
        ) * self.pan_scale_x
        self.center_y = self.pan_center_y - (
            mouse_y - self.pan_start_y
        ) * self.pan_scale_y
        height, width = self.image_shape[:2]
        self.crop_bounds(width, height)

    def mouse_callback(self, event, x, y, flags, _parameter) -> None:
        if self.image_shape is None or self.mapping is None:
            return
        mapping = self.mapping
        on_image = (
            mapping["offset_x"] <= x < mapping["offset_x"] + mapping["display_width"]
            and mapping["offset_y"]
            <= y
            < mapping["offset_y"] + mapping["display_height"]
        )

        if event == cv2.EVENT_LBUTTONDOWN:
            if not on_image:
                return
            self.is_panning = True
            self.pan_start_x = x
            self.pan_start_y = y
            self.pan_center_x = mapping["crop_x1"] + mapping["crop_width"] / 2.0
            self.pan_center_y = mapping["crop_y1"] + mapping["crop_height"] / 2.0
            self.pan_scale_x = mapping["crop_width"] / mapping["display_width"]
            self.pan_scale_y = mapping["crop_height"] / mapping["display_height"]
            return

        if event == cv2.EVENT_MOUSEMOVE and self.is_panning:
            if flags & cv2.EVENT_FLAG_LBUTTON:
                self._update_pan(x, y)
            else:
                self.is_panning = False
            return

        if event == cv2.EVENT_LBUTTONUP:
            if self.is_panning:
                self._update_pan(x, y)
                self.is_panning = False
            return

        if event != cv2.EVENT_MOUSEWHEEL or not on_image:
            return

        mouse_image_x = mapping["crop_x1"] + (
            (x - mapping["offset_x"])
            / mapping["display_width"]
            * mapping["crop_width"]
        )
        mouse_image_y = mapping["crop_y1"] + (
            (y - mapping["offset_y"])
            / mapping["display_height"]
            * mapping["crop_height"]
        )
        old_zoom = self.zoom
        self.zoom = (
            min(self.zoom * ZOOM_FACTOR, MAX_ZOOM)
            if flags > 0
            else max(self.zoom / ZOOM_FACTOR, MIN_ZOOM)
        )
        if self.zoom == old_zoom:
            return

        height, width = self.image_shape[:2]
        old_width = width / old_zoom
        old_height = height / old_zoom
        new_width = width / self.zoom
        new_height = height / self.zoom
        relative_x = (mouse_image_x - mapping["crop_x1"]) / max(old_width, 1.0)
        relative_y = (mouse_image_y - mapping["crop_y1"]) / max(old_height, 1.0)
        self.center_x = mouse_image_x - relative_x * new_width + new_width / 2.0
        self.center_y = mouse_image_y - relative_y * new_height + new_height / 2.0
        self.crop_bounds(width, height)

    def reset(self) -> None:
        self.zoom = 1.0
        if self.image_shape is not None:
            height, width = self.image_shape[:2]
            self.center_x = width / 2.0
            self.center_y = height / 2.0

    @staticmethod
    def draw_corner_labels(display) -> None:
        height, width = display.shape[:2]
        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = 2.8
        thickness = 6
        color = (0, 255, 255)
        margin = 35
        cv2.putText(
            display,
            CAMERA_CORNER_LABELS["nw"],
            (margin, margin + 70),
            font,
            scale,
            color,
            thickness,
            cv2.LINE_AA,
        )
        cv2.putText(
            display,
            CAMERA_CORNER_LABELS["sw"],
            (margin, height - margin),
            font,
            scale,
            color,
            thickness,
            cv2.LINE_AA,
        )
        southeast = CAMERA_CORNER_LABELS["se"]
        size3, _ = cv2.getTextSize(southeast, font, scale, thickness)
        cv2.putText(
            display,
            southeast,
            (width - size3[0] - margin, height - margin),
            font,
            scale,
            color,
            thickness,
            cv2.LINE_AA,
        )
        northeast = CAMERA_CORNER_LABELS["ne"]
        size4, _ = cv2.getTextSize(northeast, font, scale, thickness)
        cv2.putText(
            display,
            northeast,
            (width - size4[0] - margin, margin + 70),
            font,
            scale,
            color,
            thickness,
            cv2.LINE_AA,
        )


@dataclass
class CameraFrame:
    raw: object
    preview: object
    difference: object
    display_difference: object
    exposure_ms: float
    raw_mean: float
    raw_max: int
    contrast_auto: bool
    background_enabled: bool
    background_mode: str
    drift_dx: float
    drift_dy: float
    drift_response: float
    temporal_average_count: int
    spatial_binning: int
    mean_filter_size: int


class CameraVideoRecorder:
    """Asynchronously write the current 8-bit Camera Live image to AVI.

    The scientific source remains an 8-bit grayscale array.  For broad
    Windows-player compatibility it is replicated into three identical color
    channels before encoding; this changes only the container pixel layout,
    not the displayed grayscale information.
    """

    def __init__(self, path: Path, fps: float, width: int, height: int) -> None:
        if cv2 is None or np is None:
            raise RuntimeError(
                "录像需要 OpenCV；请安装：py -m pip install opencv-python"
            )
        self.path = Path(path)
        self.fps = float(fps)
        self.width = max(2, int(width) // 2 * 2)
        self.height = max(2, int(height) // 2 * 2)
        self.frame_queue: queue.Queue[object] = queue.Queue(maxsize=16)
        self.stats_lock = threading.Lock()
        self.frames_written = 0
        self.frames_dropped = 0
        self.start_monotonic = time.monotonic()
        self.next_frame_monotonic = self.start_monotonic
        self.accepting = True
        self.writer = None
        self.codec = ""
        self.is_color = True
        self.error: BaseException | None = None

        self.path.parent.mkdir(parents=True, exist_ok=True)
        # FFV1 is lossless but Windows' built-in player normally has no FFV1
        # decoder (0xC00D5212).  Prefer codecs that Windows can open directly.
        for codec in ("MJPG", "I420", "WMV2", "XVID"):
            candidate = cv2.VideoWriter(
                str(self.path),
                cv2.VideoWriter_fourcc(*codec),
                self.fps,
                (self.width, self.height),
                True,
            )
            if candidate.isOpened():
                self.writer = candidate
                self.codec = codec
                break
            candidate.release()
        if self.writer is None:
            raise RuntimeError(
                "无法创建Windows兼容AVI录像；MJPG/I420/WMV2/XVID编码器均不可用"
            )

        self.thread = threading.Thread(
            target=self._writer_loop,
            name="camera-video-writer",
            daemon=True,
        )
        self.thread.start()

    def reserve_frame_slot(self) -> bool:
        """Rate-limit conversion work before allocating a full canvas frame."""
        if not self.accepting or self.error is not None:
            return False
        now = time.monotonic()
        if now + 1e-9 < self.next_frame_monotonic:
            return False
        period = 1.0 / self.fps
        self.next_frame_monotonic += period
        if self.next_frame_monotonic <= now:
            self.next_frame_monotonic = now + period
        return True

    def enqueue(self, frame) -> None:
        if not self.accepting:
            return
        array = np.asarray(frame, dtype=np.uint8)
        if array.ndim != 2:
            raise ValueError("录像帧必须是二维8-bit灰度图")
        if array.shape != (self.height, self.width):
            array = cv2.resize(
                array,
                (self.width, self.height),
                interpolation=cv2.INTER_AREA,
            )
        else:
            array = array.copy()
        try:
            self.frame_queue.put_nowait(array)
        except queue.Full:
            try:
                self.frame_queue.get_nowait()
            except queue.Empty:
                pass
            with self.stats_lock:
                self.frames_dropped += 1
            try:
                self.frame_queue.put_nowait(array)
            except queue.Full:
                with self.stats_lock:
                    self.frames_dropped += 1

    def _writer_loop(self) -> None:
        try:
            while True:
                frame = self.frame_queue.get()
                if frame is None:
                    break
                # All three channels contain exactly the same displayed
                # 8-bit value, while the AVI remains directly decodable by
                # standard Windows players.
                compatible_frame = np.repeat(frame[:, :, None], 3, axis=2)
                self.writer.write(compatible_frame)
                with self.stats_lock:
                    self.frames_written += 1
        except BaseException as error:
            self.error = error
        finally:
            try:
                self.writer.release()
            except BaseException:
                pass

    def stop(self) -> dict[str, object]:
        if self.accepting:
            self.accepting = False
            while True:
                try:
                    self.frame_queue.put_nowait(None)
                    break
                except queue.Full:
                    try:
                        self.frame_queue.get_nowait()
                    except queue.Empty:
                        break
                    with self.stats_lock:
                        self.frames_dropped += 1
        self.thread.join(timeout=8.0)
        if self.thread.is_alive():
            raise TimeoutError("录像文件结束写入超过8秒，请勿立即关闭电脑")
        if self.error is not None:
            raise RuntimeError(f"录像写入失败：{self.error}")
        return self.snapshot()

    def snapshot(self) -> dict[str, object]:
        with self.stats_lock:
            written = int(self.frames_written)
            dropped = int(self.frames_dropped)
        return {
            "path": self.path,
            "fps": self.fps,
            "codec": self.codec,
            "pixel_layout": "BGR-compatible grayscale",
            "width": self.width,
            "height": self.height,
            "frames": written,
            "dropped": dropped,
            "elapsed_s": max(0.0, time.monotonic() - self.start_monotonic),
        }


class CameraAcquisitionWorker:
    """Own the PCO camera entirely inside one non-GUI worker thread."""

    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.frames: queue.Queue[CameraFrame] = queue.Queue(maxsize=1)
        self.errors: queue.Queue[BaseException] = queue.Queue(maxsize=1)
        self.stop_event = threading.Event()
        self.settings_lock = threading.Lock()
        # Start in a stable fixed-range view.  Press [A] to opt into
        # viewport-based automatic contrast.
        self.contrast_auto = False
        self.fixed_low = 0.0
        self.fixed_high = 65535.0
        self.last_low = 0.0
        self.last_high = 65535.0
        self.fixed_difference_max_abs = 1.0
        self.fixed_difference_center = 0.0
        self.last_difference_max_abs = 1.0
        self.last_difference_center = 0.0
        self.difference_contrast_valid = False
        self.difference_manual_clim: tuple[float, float] | None = None
        self.difference_temporal_average_count = 1
        self.difference_spatial_binning = 1
        self.difference_mean_filter_size = 1
        self.difference_average_reset_requested = True
        # The following arrays are owned only by the acquisition thread.
        self._difference_average_sum = None
        self._difference_average_samples = 0
        self._difference_average_previous = None
        self.requested_exposure_s = EXPOSURE_S
        self.active_exposure_s = EXPOSURE_S
        self.exposure_update_requested = False
        self.background_mode = "off"
        self.last_background_mode = "tracking"
        self.background_enabled = False
        self.background_capture_requested = False
        self.background = None
        self.thread = threading.Thread(
            target=self._run,
            name="pco-camera",
            daemon=True,
        )

    def start(self) -> None:
        self.thread.start()

    def stop(self) -> None:
        self.stop_event.set()
        if self.thread.is_alive():
            self.thread.join(timeout=3.0)

    def toggle_contrast(self) -> bool:
        with self.settings_lock:
            if self.difference_manual_clim is not None:
                # [A] is the quick escape from a GUI-entered manual CLim.
                self.difference_manual_clim = None
                self.contrast_auto = True
                self.difference_contrast_valid = False
                return True
            if self.contrast_auto:
                self.fixed_low = self.last_low
                self.fixed_high = self.last_high
                if self.difference_contrast_valid:
                    self.fixed_difference_max_abs = (
                        self.last_difference_max_abs
                    )
                    self.fixed_difference_center = self.last_difference_center
                self.contrast_auto = False
            else:
                self.contrast_auto = True
                # Recalibrate immediately from the current visible difference
                # image instead of easing from a possibly stale fixed range.
                self.difference_contrast_valid = False
            return self.contrast_auto

    def update_auto_contrast_bounds(self, low: float, high: float) -> None:
        """Receive the GUI viewport's latest auto-contrast limits."""
        with self.settings_lock:
            if self.contrast_auto:
                self.last_low = float(low)
                self.last_high = float(high)

    def resolve_difference_contrast(
        self,
        auto_center: float,
        auto_max_abs: float,
    ) -> tuple[float, float]:
        """Return temporally stable centre/range for the difference preview."""
        candidate_center = float(auto_center)
        candidate = max(float(auto_max_abs), DIFFERENCE_MIN_HALF_RANGE)
        with self.settings_lock:
            if self.difference_manual_clim is not None:
                low, high = self.difference_manual_clim
                return (low + high) / 2.0, (high - low) / 2.0
            if self.contrast_auto:
                if not self.difference_contrast_valid:
                    self.last_difference_center = candidate_center
                    self.last_difference_max_abs = candidate
                else:
                    self.last_difference_center += DIFFERENCE_CENTER_SMOOTHING * (
                        candidate_center - self.last_difference_center
                    )
                    smoothing = (
                        DIFFERENCE_EXPAND_SMOOTHING
                        if candidate > self.last_difference_max_abs
                        else DIFFERENCE_CONTRACT_SMOOTHING
                    )
                    self.last_difference_max_abs += smoothing * (
                        candidate - self.last_difference_max_abs
                    )
                self.difference_contrast_valid = True
                return (
                    self.last_difference_center,
                    self.last_difference_max_abs,
                )
            if not self.difference_contrast_valid:
                # Fixed was selected before any difference frame existed.
                self.fixed_difference_max_abs = candidate
                self.fixed_difference_center = candidate_center
                self.last_difference_max_abs = candidate
                self.last_difference_center = candidate_center
                self.difference_contrast_valid = True
            return self.fixed_difference_center, self.fixed_difference_max_abs

    def set_difference_manual_clim(self, low: float, high: float) -> None:
        low = float(low)
        high = float(high)
        if not math.isfinite(low) or not math.isfinite(high):
            raise ValueError("CLim 上下限必须是有限数值")
        if high <= low:
            raise ValueError("CLim 上限必须大于下限")
        with self.settings_lock:
            self.difference_manual_clim = (low, high)

    def clear_difference_manual_clim(self) -> None:
        with self.settings_lock:
            self.difference_manual_clim = None
            self.contrast_auto = True
            self.difference_contrast_valid = False

    def difference_contrast_state(self) -> tuple[str, tuple[float, float] | None]:
        """Return mode and the CLim currently used by the display."""
        with self.settings_lock:
            manual = self.difference_manual_clim
            if manual is not None:
                return "MANUAL", manual
            if self.contrast_auto:
                if not self.difference_contrast_valid:
                    return "AUTO", None
                center = self.last_difference_center
                half_range = self.last_difference_max_abs
                return "AUTO", (center - half_range, center + half_range)
            if not self.difference_contrast_valid:
                return "FIXED", None
            center = self.fixed_difference_center
            half_range = self.fixed_difference_max_abs
            return "FIXED", (center - half_range, center + half_range)

    def set_difference_display_average(
        self,
        temporal_count: int,
        spatial_binning: int,
        mean_filter_size: int,
    ) -> None:
        temporal_count = int(temporal_count)
        if temporal_count not in {1, 2, 4, 8}:
            raise ValueError("差分数据平均帧数只能是 1、2、4 或 8")
        spatial_binning = int(spatial_binning)
        if spatial_binning not in {1, 2, 4, 8}:
            raise ValueError("显示 Binning 只能是 1×1、2×2、4×4 或 8×8")
        mean_filter_size = int(mean_filter_size)
        if mean_filter_size not in {1, 2, 4}:
            raise ValueError("Mean filter 只能是关闭、2×2 或 4×4")
        with self.settings_lock:
            changed = (
                temporal_count != self.difference_temporal_average_count
                or spatial_binning != self.difference_spatial_binning
                or mean_filter_size != self.difference_mean_filter_size
            )
            self.difference_temporal_average_count = temporal_count
            self.difference_spatial_binning = spatial_binning
            self.difference_mean_filter_size = mean_filter_size
            if changed:
                self.difference_average_reset_requested = True
                self.difference_contrast_valid = False

    def difference_display_average_state(self) -> tuple[int, int, int]:
        with self.settings_lock:
            return (
                self.difference_temporal_average_count,
                self.difference_spatial_binning,
                self.difference_mean_filter_size,
            )

    def request_exposure_ms(self, exposure_ms: float) -> None:
        exposure_ms = float(exposure_ms)
        if not math.isfinite(exposure_ms):
            raise ValueError("曝光时间必须是有限数值")
        if not 0.01 <= exposure_ms <= 10_000.0:
            raise ValueError("曝光时间必须在 0.01–10000 ms 范围内")
        with self.settings_lock:
            self.requested_exposure_s = exposure_ms / 1000.0
            self.exposure_update_requested = True

    def active_exposure_ms(self) -> float:
        with self.settings_lock:
            return self.active_exposure_s * 1000.0

    def _reset_difference_display_average(self) -> None:
        self._difference_average_sum = None
        self._difference_average_samples = 0
        self._difference_average_previous = None

    def _difference_for_display(
        self,
        difference,
        temporal_count: int,
        spatial_binning: int,
        mean_filter_size: int,
        reset: bool,
    ):
        if reset:
            self._reset_difference_display_average()
        source = np.asarray(difference, dtype=np.float32)
        if temporal_count <= 1:
            display = source
        else:
            if (
                self._difference_average_sum is not None
                and self._difference_average_sum.shape != source.shape
            ):
                self._reset_difference_display_average()
            if self._difference_average_sum is None:
                self._difference_average_sum = source.copy()
                self._difference_average_samples = 1
            else:
                self._difference_average_sum += source
                self._difference_average_samples += 1
            samples = self._difference_average_samples
            if samples >= temporal_count:
                display = self._difference_average_sum / float(temporal_count)
                self._difference_average_previous = display
                self._difference_average_sum = None
                self._difference_average_samples = 0
            elif self._difference_average_previous is None:
                # Initial fill: progressively improve instead of showing a
                # blank image while the first averaging block fills.
                display = self._difference_average_sum / float(samples)
            else:
                # Cross-fade the last completed block into the accumulating
                # block.  This updates every frame with only two full-size
                # float arrays instead of retaining every frame in memory.
                remaining = temporal_count - samples
                display = (
                    self._difference_average_previous
                    * (remaining / float(temporal_count))
                    + self._difference_average_sum / float(temporal_count)
                )
        if spatial_binning > 1:
            display = spatial_bin_average_full_size(display, spatial_binning)
        if mean_filter_size > 1:
            display = mean_filter_full_size(display, mean_filter_size)
        return display

    def toggle_background(self) -> bool:
        with self.settings_lock:
            if self.background_mode == "off":
                self.background_mode = self.last_background_mode
                self.difference_contrast_valid = False
                self.difference_average_reset_requested = True
            else:
                self.last_background_mode = self.background_mode
                self.background_mode = "off"
            self.background_enabled = self.background_mode != "off"
            if self.background_enabled and self.background is None:
                self.background_capture_requested = True
            elif not self.background_enabled:
                self.background_capture_requested = False
            return self.background_enabled

    def set_background_mode(self, mode: str) -> str:
        if mode not in {"off", "plain", "tracking"}:
            raise ValueError(f"未知差分模式：{mode}")
        with self.settings_lock:
            previous_mode = self.background_mode
            self.background_mode = mode
            self.background_enabled = mode != "off"
            if mode != previous_mode and mode != "off":
                self.difference_contrast_valid = False
                self.difference_average_reset_requested = True
            if self.background_enabled:
                self.last_background_mode = mode
                if self.background is None:
                    self.background_capture_requested = True
            else:
                self.background_capture_requested = False
            return self.background_mode

    def capture_background(self) -> None:
        with self.settings_lock:
            if self.background_mode == "off":
                self.background_mode = self.last_background_mode
            self.background_enabled = True
            self.background_capture_requested = True
            self.difference_contrast_valid = False
            self.difference_average_reset_requested = True

    @staticmethod
    def _make_preview(image_raw, low: float, high: float):
        preview = np.clip(
            (image_raw.astype(np.float32) - low)
            * 255.0
            / max(high - low, 1.0),
            0,
            255,
        )
        return preview.astype(np.uint8)

    def _put_latest(self, frame: CameraFrame) -> None:
        try:
            self.frames.put_nowait(frame)
            return
        except queue.Full:
            pass
        try:
            self.frames.get_nowait()
        except queue.Empty:
            pass
        try:
            self.frames.put_nowait(frame)
        except queue.Full:
            pass

    def _run(self) -> None:
        camera = None
        try:
            camera = pco.Camera()
            camera.default_configuration()
            camera.exposure_time = EXPOSURE_S
            camera.configuration = {"timestamp": "off", "metadata": "off"}
            camera.record(RING_BUFFER_FRAMES, "ring buffer")
            self.logger("PCO 相机实时预览已启动")

            while not self.stop_event.is_set():
                with self.settings_lock:
                    requested_exposure = (
                        self.requested_exposure_s
                        if self.exposure_update_requested
                        else None
                    )
                    self.exposure_update_requested = False
                    previous_exposure = self.active_exposure_s
                if requested_exposure is not None:
                    try:
                        camera.stop()
                        camera.exposure_time = requested_exposure
                        camera.record(RING_BUFFER_FRAMES, "ring buffer")
                    except BaseException as error:
                        self.logger(f"相机曝光更新失败：{error}")
                        # Best effort: restore the previous working stream.
                        try:
                            camera.stop()
                        except BaseException:
                            pass
                        camera.exposure_time = previous_exposure
                        camera.record(RING_BUFFER_FRAMES, "ring buffer")
                    else:
                        self.background = None
                        self._reset_difference_display_average()
                        with self.settings_lock:
                            self.active_exposure_s = requested_exposure
                            self.difference_contrast_valid = False
                            self.difference_average_reset_requested = True
                            if self.background_mode != "off":
                                self.background_capture_requested = True
                        self.logger(
                            "相机曝光已更新："
                            f"{requested_exposure * 1000.0:g} ms；差分背景将重采"
                        )
                camera.wait_for_new_image()
                image_raw, _metadata = camera.image(0xFFFFFFFF)
                image_raw = orient_camera_image(image_raw)

                with self.settings_lock:
                    auto = self.contrast_auto
                    fixed_low = self.fixed_low
                    fixed_high = self.fixed_high
                    last_low = self.last_low
                    last_high = self.last_high
                    background_mode = self.background_mode
                    background_enabled = background_mode != "off"
                    temporal_average_count = (
                        self.difference_temporal_average_count
                    )
                    spatial_binning = self.difference_spatial_binning
                    mean_filter_size = self.difference_mean_filter_size
                    reset_display_average = (
                        self.difference_average_reset_requested
                    )
                    if reset_display_average:
                        self.difference_average_reset_requested = False
                    capture_background = self.background_capture_requested
                    if capture_background:
                        self.background_capture_requested = False

                if capture_background:
                    self.background = image_raw.copy()
                    self.logger("相机背景已采集")

                if background_enabled:
                    if self.background is None:
                        self.background = image_raw.copy()
                    if background_mode == "tracking":
                        difference, dx, dy, response = subtract_background_after_drift(
                            image_raw, self.background
                        )
                    else:
                        difference = (
                            image_raw.astype(np.float32)
                            - self.background.astype(np.float32)
                        )
                        dx, dy, response = 0.0, 0.0, 0.0
                    display_difference = self._difference_for_display(
                        difference,
                        temporal_average_count,
                        spatial_binning,
                        mean_filter_size,
                        reset_display_average,
                    )
                    # Display-side contrast needs the current viewport, which
                    # is owned by Tk.  Keep only a shape-compatible placeholder
                    # here; TkCameraWindow._draw builds the visible preview.
                    preview = np.zeros(image_raw.shape, dtype=np.uint8)
                else:
                    difference = None
                    display_difference = None
                    if reset_display_average:
                        self._reset_difference_display_average()
                    dx, dy, response = 0.0, 0.0, 0.0
                    if auto:
                        # The Tk display thread updates these values from the
                        # actual zoomed/panned viewport.  Never recalculate
                        # auto contrast from the full sensor frame here.
                        low, high = last_low, last_high
                    else:
                        low = fixed_low
                        high = fixed_high
                    preview = self._make_preview(image_raw, low, high)

                frame = CameraFrame(
                    raw=image_raw,
                    preview=preview,
                    difference=difference,
                    display_difference=display_difference,
                    exposure_ms=self.active_exposure_s * 1000.0,
                    raw_mean=float(np.mean(image_raw)),
                    raw_max=int(np.max(image_raw)),
                    contrast_auto=auto,
                    background_enabled=background_enabled,
                    background_mode=background_mode,
                    drift_dx=dx,
                    drift_dy=dy,
                    drift_response=response,
                    temporal_average_count=temporal_average_count,
                    spatial_binning=spatial_binning,
                    mean_filter_size=mean_filter_size,
                )
                self._put_latest(frame)
        except BaseException as error:
            try:
                self.errors.put_nowait(error)
            except queue.Full:
                pass
        finally:
            if camera is not None:
                try:
                    camera.stop()
                except BaseException:
                    pass
                try:
                    camera.close()
                except BaseException:
                    pass
            self.logger("PCO 相机实时预览已停止")


class TkCameraWindow:
    """Display camera frames using Tk only; no OpenCV GUI event loop."""

    def __init__(self, root: tk.Tk, app) -> None:
        if CAMERA_IMPORT_ERROR is not None:
            raise RuntimeError(
                "缺少相机依赖。请安装 pco、numpy、Pillow，并确认 PCO 驱动正常。\n\n"
                + str(CAMERA_IMPORT_ERROR)
            )

        self.root = root
        self.app = app
        self.window = tk.Toplevel(root)
        # Acquisition starts with the application, but the expensive/large
        # live view stays folded away until the Camera Live tab opens it.
        self.window.withdraw()
        self.window.title(CAMERA_WINDOW)
        self.window.geometry(geometry_string(self.app.window_layout["camera"]))
        camera_geometry = self.app.window_layout["camera"]
        self.window.minsize(
            min(camera_geometry[0], max(360, int(520 * self.app.ui_scale))),
            min(camera_geometry[1], max(280, int(400 * self.app.ui_scale))),
        )
        self.window.protocol("WM_DELETE_WINDOW", self.hide)
        self.window_visible = False

        self.canvas = tk.Canvas(self.window, bg="black", highlightthickness=0)
        self.canvas.pack(fill="both", expand=True)
        self.canvas.bind("<MouseWheel>", self._mouse_wheel)
        self.canvas.bind("<Button-4>", lambda event: self._zoom_at(event.x, event.y, 1))
        self.canvas.bind("<Button-5>", lambda event: self._zoom_at(event.x, event.y, -1))
        self.canvas.bind("<ButtonPress-1>", self._pan_start)
        self.canvas.bind("<B1-Motion>", self._pan_move)
        self.canvas.bind("<ButtonRelease-1>", self._pan_end)
        self.window.bind("<KeyPress-a>", self._toggle_contrast)
        self.window.bind("<KeyPress-A>", self._toggle_contrast)
        self.window.bind("<KeyPress-b>", self._toggle_background)
        self.window.bind("<KeyPress-B>", self._toggle_background)
        self.window.bind("<KeyPress-n>", self._capture_background)
        self.window.bind("<KeyPress-N>", self._capture_background)
        self.window.bind("<KeyPress-c>", self._clear_roi)
        self.window.bind("<KeyPress-C>", self._clear_roi)
        self.window.bind("<KeyPress-r>", self._reset_zoom)
        self.window.bind("<KeyPress-R>", self._reset_zoom)
        self.window.bind("<KeyPress-m>", lambda _event: self.app.toggle_100x_marker())
        self.window.bind("<KeyPress-M>", lambda _event: self.app.toggle_100x_marker())
        self.window.bind("<KeyPress-q>", lambda _event: self.app.request_close())
        self.window.bind("<Escape>", lambda _event: self.app.request_close())
        self.window.focus_set()
        self.window.after_idle(lambda: force_english_input_mode(self.window))

        self.worker = CameraAcquisitionWorker(self.app.thread_log)
        self.latest_frame: CameraFrame | None = None
        # Marker-free copy of the most recently rendered image plus its Canvas
        # placement.  The black letterbox is assembled only when Save is
        # clicked, avoiding a full-Canvas allocation on every live frame.
        self.latest_display_image = None
        self.latest_display_geometry = None
        self.photo = None
        self.mapping = None
        self.zoom = 1.0
        self.center_x = None
        self.center_y = None
        self.panning = False
        self.pan_start_x = 0
        self.pan_start_y = 0
        self.pan_center_x = 0.0
        self.pan_center_y = 0.0
        self.selecting_roi = False
        self.roi_start = None
        self.roi_end = None
        self.roi = None
        self.roi_overlay_id = None
        self.roi_label_id = None
        self.objective_100x_marker_visible = False
        self.video_recorder: CameraVideoRecorder | None = None
        self.video_status_last_update = 0.0
        self.error_shown = False
        self.connection_announced = False
        self.after_id = None
        # Pausing Camera Live means pausing only the expensive Tk/Pillow
        # rendering path.  Acquisition keeps running and _poll keeps draining
        # the queue, so resuming can immediately draw the newest frame.
        self.render_pause_count = 0
        self.render_pause_reason = ""

        self.worker.start()
        self.after_id = self.window.after(15, self._poll)

    @property
    def rendering_paused(self) -> bool:
        return self.render_pause_count > 0

    def show(self) -> None:
        """Show the existing live window without restarting acquisition."""
        try:
            if not self.window.winfo_exists():
                raise RuntimeError("Camera Live 窗口已关闭")
            self.window.deiconify()
            self.window.lift()
            self.window.focus_set()
            self.window_visible = True
            self.app.camera_window_visibility_changed(True)
            if self.latest_frame is not None and not self.rendering_paused:
                self._draw(self.latest_frame)
        except tk.TclError as error:
            raise RuntimeError("无法显示 Camera Live 窗口") from error

    def hide(self) -> None:
        """Fold away only the display; camera acquisition keeps running."""
        self.window_visible = False
        try:
            if self.window.winfo_exists():
                self.window.withdraw()
        except tk.TclError:
            pass
        self.app.camera_window_visibility_changed(False)

    def pause_rendering(self, reason: str = "后台操作") -> None:
        """Temporarily stop live drawing without stopping camera acquisition."""
        self.render_pause_count += 1
        self.render_pause_reason = str(reason or "后台操作")
        if self.render_pause_count != 1:
            return
        try:
            width = max(self.canvas.winfo_width(), 320)
            height = max(self.canvas.winfo_height(), 240)
            self.canvas.delete("camera_pause_overlay")
            self.canvas.create_rectangle(
                12,
                height - 48,
                width - 12,
                height - 12,
                fill="#1e293b",
                outline="#f4c542",
                width=2,
                tags="camera_pause_overlay",
            )
            self.canvas.create_text(
                width / 2,
                height - 30,
                text=f"Live display paused · {self.render_pause_reason}",
                fill="#ffe66d",
                font=(self.app.ui_font_family, 11, "bold"),
                tags="camera_pause_overlay",
            )
            self.canvas.tag_raise("camera_pause_overlay")
        except tk.TclError:
            pass

    def resume_rendering(self) -> None:
        """Resume live drawing and immediately show the latest acquired frame."""
        if self.render_pause_count <= 0:
            return
        self.render_pause_count -= 1
        if self.render_pause_count > 0:
            return
        self.render_pause_reason = ""
        try:
            self.canvas.delete("camera_pause_overlay")
        except tk.TclError:
            pass
        frame = self.latest_frame
        if frame is not None:
            try:
                if self.window.winfo_exists() and self.window_visible:
                    self._draw(frame)
            except tk.TclError:
                pass

    def stop(self) -> None:
        if self.video_recorder is not None:
            try:
                self.stop_video_recording()
            except BaseException as error:
                self.app.append_log(f"相机录像结束失败：{error}")
        try:
            if self.after_id is not None and self.window.winfo_exists():
                self.window.after_cancel(self.after_id)
        except tk.TclError:
            pass
        self.after_id = None
        self.worker.stop()

    def close(self) -> None:
        """Stop acquisition and destroy only the Camera Live toplevel."""
        self.window_visible = False
        self.stop()
        try:
            if self.window.winfo_exists():
                self.window.destroy()
        except tk.TclError:
            pass

    def _poll(self) -> None:
        try:
            error = self.worker.errors.get_nowait()
        except queue.Empty:
            error = None
        if error is not None and not self.error_shown:
            self.error_shown = True
            self.app.append_log(f"相机错误：{error}")
            self.app.camera_start_failed(error)
            messagebox.showerror(
                "相机采集失败",
                str(error) + "\n\nLED 控制窗口仍可继续使用。",
                parent=self.root,
            )
            return

        newest = None
        while True:
            try:
                newest = self.worker.frames.get_nowait()
            except queue.Empty:
                break
        if newest is not None:
            self.latest_frame = newest
            if not self.connection_announced:
                self.connection_announced = True
                self.app.camera_connection_ready()
            # Keep acquiring the newest frame while selecting an ROI, but
            # freeze the expensive image conversion/resize.  Mouse motion then
            # updates only two lightweight Canvas overlay items.
            if (
                (self.window_visible or self.video_recorder is not None)
                and not self.selecting_roi
                and not self.rendering_paused
            ):
                self._draw(newest)
            elif not self.selecting_roi:
                # A folded live window must not stop scientific acquisition.
                # Keep ROI streams current without paying the Tk/Pillow resize
                # cost; recording still takes the full _draw path above.
                self._ingest_roi_values(newest)
                self.app.update_difference_status(
                    newest.background_mode,
                    newest.drift_dx,
                    newest.drift_dy,
                    newest.drift_response,
                )
                self.app.camera_exposure_status_var.set(
                    f"{newest.exposure_ms:g} ms"
                )

        try:
            if self.window.winfo_exists():
                self.after_id = self.window.after(15, self._poll)
        except tk.TclError:
            self.after_id = None

    def _crop_bounds(self, width: int, height: int):
        if self.center_x is None:
            self.center_x = width / 2.0
        if self.center_y is None:
            self.center_y = height / 2.0
        crop_width = max(1, int(width / self.zoom))
        crop_height = max(1, int(height / self.zoom))
        self.center_x = float(
            np.clip(self.center_x, crop_width / 2.0, width - crop_width / 2.0)
        )
        self.center_y = float(
            np.clip(self.center_y, crop_height / 2.0, height - crop_height / 2.0)
        )
        x1 = int(np.clip(round(self.center_x - crop_width / 2.0), 0, width - crop_width))
        y1 = int(np.clip(round(self.center_y - crop_height / 2.0), 0, height - crop_height))
        return x1, y1, x1 + crop_width, y1 + crop_height

    def _draw(self, frame: CameraFrame) -> None:
        if self.rendering_paused:
            return
        image_height, image_width = frame.raw.shape[:2]
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        x1, y1, x2, y2 = self._crop_bounds(image_width, image_height)
        visible_bounds = (x1, y1, x2, y2)
        active_difference_clim = None
        if frame.difference is not None:
            display_difference = (
                frame.display_difference
                if frame.display_difference is not None
                else frame.difference
            )
            # AUTO follows robust statistics from the visible viewport;
            # Fixed locks them and Manual directly supplies MATLAB-like CLim.
            auto_center, auto_max_abs = difference_contrast_parameters(
                display_difference, visible_bounds
            )
            active_center, active_max_abs = self.worker.resolve_difference_contrast(
                auto_center,
                auto_max_abs
            )
            preview = difference_preview(
                display_difference,
                max_abs=active_max_abs,
                center=active_center,
            )
            active_difference_clim = (
                active_center - active_max_abs,
                active_center + active_max_abs,
            )
        elif frame.contrast_auto:
            low, high = auto_contrast_limits(frame.raw, visible_bounds)
            self.worker.update_auto_contrast_bounds(low, high)
            preview = self.worker._make_preview(frame.raw, low, high)
        else:
            preview = frame.preview
        cropped = preview[y1:y2, x1:x2]
        scale = min(canvas_width / cropped.shape[1], canvas_height / cropped.shape[0])
        display_width = max(1, int(cropped.shape[1] * scale))
        display_height = max(1, int(cropped.shape[0] * scale))
        offset_x = (canvas_width - display_width) // 2
        offset_y = (canvas_height - display_height) // 2

        pil_image = Image.fromarray(cropped)
        pil_image = pil_image.resize(
            (display_width, display_height), Image.Resampling.BILINEAR
        )
        display_array = np.asarray(pil_image, dtype=np.uint8)
        self.latest_display_image = display_array.copy()
        self.latest_display_geometry = (
            offset_x,
            offset_y,
            canvas_width,
            canvas_height,
        )
        self._record_current_8bit_view(
            display_array,
            offset_x,
            offset_y,
            canvas_width,
            canvas_height,
        )
        self.photo = ImageTk.PhotoImage(pil_image)
        self.canvas.delete("all")
        self.roi_overlay_id = None
        self.roi_label_id = None
        self.canvas.create_image(offset_x, offset_y, image=self.photo, anchor="nw")
        self.mapping = {
            "crop_x1": x1,
            "crop_y1": y1,
            "crop_width": x2 - x1,
            "crop_height": y2 - y1,
            "offset_x": offset_x,
            "offset_y": offset_y,
            "display_width": display_width,
            "display_height": display_height,
            "image_width": image_width,
            "image_height": image_height,
        }

        margin = 35
        label_font = (self.app.ui_font_family, 46, "bold")
        self.canvas.create_text(
            margin,
            margin,
            text=CAMERA_CORNER_LABELS["nw"],
            fill="yellow",
            font=label_font,
            anchor="nw",
        )
        self.canvas.create_text(
            margin,
            canvas_height - margin,
            text=CAMERA_CORNER_LABELS["sw"],
            fill="yellow",
            font=label_font,
            anchor="sw",
        )
        self.canvas.create_text(
            canvas_width - margin,
            canvas_height - margin,
            text=CAMERA_CORNER_LABELS["se"],
            fill="yellow",
            font=label_font,
            anchor="se",
        )
        self.canvas.create_text(
            canvas_width - margin,
            margin,
            text=CAMERA_CORNER_LABELS["ne"],
            fill="yellow",
            font=label_font,
            anchor="ne",
        )

        if frame.difference is not None:
            contrast_mode, active_clim = self.worker.difference_contrast_state()
            if active_clim is None:
                contrast = contrast_mode
            else:
                contrast = (
                    f"{contrast_mode} CLim "
                    f"[{active_clim[0]:.4g}, {active_clim[1]:.4g}]"
                )
        else:
            contrast = "AUTO" if frame.contrast_auto else "FIXED"
        temporal_average = frame.temporal_average_count
        spatial_binning = frame.spatial_binning
        mean_filter_size = frame.mean_filter_size
        average_text = f"Avg {temporal_average}"
        if spatial_binning > 1:
            average_text += f" + Bin {spatial_binning}x{spatial_binning}"
        if mean_filter_size > 1:
            average_text += f" + Mean {mean_filter_size}x{mean_filter_size}"
        exposure_text = f"Exp {frame.exposure_ms:g} ms"
        if frame.background_mode == "tracking":
            camera_status = (
                f"Tracking subtraction ON   dx {frame.drift_dx:+.2f}   "
                f"dy {frame.drift_dy:+.2f}   {exposure_text}   "
                f"{average_text}   Contrast {contrast}"
            )
            status_color = "#6dff6d"
        elif frame.background_mode == "plain":
            camera_status = (
                f"Plain subtraction ON   Zoom {self.zoom:.2f}x   "
                f"{exposure_text}   {average_text}   Contrast {contrast}"
            )
            status_color = "#ffe66d"
        else:
            camera_status = (
                f"Zoom {self.zoom:.2f}x   {exposure_text}   "
                f"Contrast {contrast}   BG OFF"
            )
            status_color = "#6de7ff"
        self.canvas.create_text(
            canvas_width / 2,
            17,
            text=camera_status,
            fill=status_color,
            font=(self.app.ui_font_family, self.app.ui_font_size + 2, "bold"),
            anchor="n",
        )
        self.canvas.create_text(
            canvas_width / 2,
            42,
            text=(
                f"Raw mean {frame.raw_mean:.1f}   max {frame.raw_max}   "
                "[A] contrast  [B] BG  [N] new BG  [C] clear ROI  "
                "[R] reset  [M] marker  [Q] quit"
            ),
            fill="yellow",
            font=(self.app.ui_font_family, self.app.ui_font_size),
            anchor="n",
        )
        if self.video_recorder is not None:
            self.canvas.create_text(
                12,
                10,
                text="● REC",
                fill="#ff2d2d",
                font=(
                    self.app.ui_font_family,
                    self.app.ui_font_size + 2,
                    "bold",
                ),
                anchor="nw",
            )
        self._draw_roi(frame)
        self._draw_100x_marker()
        self._draw_measurement_marker()
        self.app.update_difference_status(
            frame.background_mode,
            frame.drift_dx,
            frame.drift_dy,
            frame.drift_response,
        )
        self.app.camera_exposure_status_var.set(f"{frame.exposure_ms:g} ms")
        if frame.difference is not None and active_difference_clim is not None:
            self.app.update_difference_histogram(
                display_difference,
                visible_bounds,
                active_difference_clim,
            )

    def _canvas_to_image(self, x: int, y: int):
        if not self._on_image(x, y):
            return None
        mapping = self.mapping
        image_x = mapping["crop_x1"] + (
            (x - mapping["offset_x"])
            / mapping["display_width"]
            * mapping["crop_width"]
        )
        image_y = mapping["crop_y1"] + (
            (y - mapping["offset_y"])
            / mapping["display_height"]
            * mapping["crop_height"]
        )
        return image_x, image_y

    def start_video_recording(self, path: Path, fps: float) -> dict[str, object]:
        if self.video_recorder is not None:
            raise RuntimeError("Camera Live录像已经在进行")
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        recorder = CameraVideoRecorder(path, fps, canvas_width, canvas_height)
        self.video_recorder = recorder
        self.video_status_last_update = 0.0
        return recorder.snapshot()

    def stop_video_recording(self) -> dict[str, object] | None:
        recorder = self.detach_video_recorder()
        if recorder is None:
            return None
        return recorder.stop()

    def detach_video_recorder(self) -> CameraVideoRecorder | None:
        recorder = self.video_recorder
        self.video_recorder = None
        return recorder

    def _record_current_8bit_view(
        self,
        display_image,
        offset_x: int,
        offset_y: int,
        canvas_width: int,
        canvas_height: int,
    ) -> None:
        recorder = self.video_recorder
        if recorder is None or not recorder.reserve_frame_slot():
            return
        frame = np.zeros((canvas_height, canvas_width), dtype=np.uint8)
        image = np.asarray(display_image, dtype=np.uint8)
        paste_height = min(image.shape[0], canvas_height - offset_y)
        paste_width = min(image.shape[1], canvas_width - offset_x)
        if paste_height > 0 and paste_width > 0:
            frame[
                offset_y : offset_y + paste_height,
                offset_x : offset_x + paste_width,
            ] = image[:paste_height, :paste_width]
        measurement_marker = self.app.current_camera_marker_text()
        if measurement_marker:
            font_scale = max(0.45, min(canvas_width, canvas_height) / 1400.0)
            thickness = max(1, int(round(font_scale * 2.0)))
            (text_width, text_height), baseline = cv2.getTextSize(
                measurement_marker,
                cv2.FONT_HERSHEY_SIMPLEX,
                font_scale,
                thickness,
            )
            text_x = max(6, (canvas_width - text_width) // 2)
            text_y = canvas_height - 14
            cv2.rectangle(
                frame,
                (text_x - 5, text_y - text_height - 6),
                (min(canvas_width - 1, text_x + text_width + 5), text_y + baseline + 4),
                0,
                -1,
            )
            cv2.putText(
                frame,
                measurement_marker,
                (text_x, text_y),
                cv2.FONT_HERSHEY_SIMPLEX,
                font_scale,
                255,
                thickness,
                cv2.LINE_AA,
            )
        recorder.enqueue(frame)
        now = time.monotonic()
        if now - self.video_status_last_update >= 0.25:
            self.video_status_last_update = now
            self.app.update_camera_video_status(recorder.snapshot())

    def set_100x_marker_visible(self, visible: bool) -> None:
        """Show or hide the fixed 5x-to-100x field-of-view guide."""
        self.objective_100x_marker_visible = bool(visible)
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)

    def _draw_100x_marker(self) -> None:
        self.canvas.delete("objective_100x_marker")
        mapping = self.mapping
        if not self.objective_100x_marker_visible or mapping is None:
            return
        image_x = (
            mapping["image_width"] * OBJECTIVE_100X_MARKER_X_FRACTION
        )
        image_y = (
            mapping["image_height"] * OBJECTIVE_100X_MARKER_Y_FRACTION
        )
        center_x = mapping["offset_x"] + (
            (image_x - mapping["crop_x1"])
            / mapping["crop_width"]
            * mapping["display_width"]
        )
        center_y = mapping["offset_y"] + (
            (image_y - mapping["crop_y1"])
            / mapping["crop_height"]
            * mapping["display_height"]
        )
        image_to_canvas_scale = min(
            mapping["display_width"] / mapping["crop_width"],
            mapping["display_height"] / mapping["crop_height"],
        )
        radius = max(
            10.0,
            min(mapping["image_width"], mapping["image_height"])
            * OBJECTIVE_100X_MARKER_RADIUS_FRACTION
            * image_to_canvas_scale,
        )
        self.canvas.create_oval(
            center_x - radius,
            center_y - radius,
            center_x + radius,
            center_y + radius,
            outline="#ff2d00",
            width=4,
            tags="objective_100x_marker",
        )
        self.canvas.create_text(
            center_x,
            center_y - radius - 5,
            text="100× FOV",
            fill="#ff2d00",
            font=(self.app.ui_font_family, self.app.ui_font_size, "bold"),
            anchor="s",
            tags="objective_100x_marker",
        )
        self.canvas.tag_raise("objective_100x_marker")

    def _draw_measurement_marker(self) -> None:
        marker_text = self.app.current_camera_marker_text()
        if not marker_text:
            return
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        text_id = self.canvas.create_text(
            canvas_width / 2,
            canvas_height - 12,
            text=marker_text,
            fill="#ffd54f",
            font=(self.app.ui_font_family, 11, "bold"),
            anchor="s",
            tags="measurement_marker",
        )
        bounds = self.canvas.bbox(text_id)
        if bounds is not None:
            left, top, right, bottom = bounds
            background_id = self.canvas.create_rectangle(
                left - 5,
                top - 3,
                right + 5,
                bottom + 3,
                fill="#111111",
                outline="#ffd54f",
                width=1,
                tags="measurement_marker",
            )
            self.canvas.tag_lower(background_id, text_id)
        self.canvas.tag_raise("measurement_marker")

    def _ingest_roi_values(self, frame: CameraFrame) -> str:
        """Update raw/difference ROI streams without requiring a visible UI."""
        roi = self.roi
        if self.selecting_roi and self.roi_start is not None and self.roi_end is not None:
            x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
            y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
            roi = {
                "cx": (x1 + x2) / 2.0,
                "cy": (y1 + y2) / 2.0,
                "w": x2 - x1,
                "h": y2 - y1,
                "angle": 0.0,
            }
        if roi is None or self.mapping is None:
            return ""
        raw_roi_values = values_inside_rotated_roi(frame.raw, roi)
        raw_mean_value = None
        if raw_roi_values.size:
            raw_mean_value = float(np.mean(raw_roi_values))
            if not self.selecting_roi:
                self.app.ingest_led_roi_sample(raw_mean_value)

        if frame.difference is None:
            if raw_mean_value is None:
                label = "ROI outside image"
            else:
                label = f"Raw ROI mean {raw_mean_value:.3f} · BG not subtracted"
        else:
            processed_difference = (
                frame.display_difference
                if frame.display_difference is not None
                else frame.difference
            )
            roi_values = values_inside_rotated_roi(processed_difference, roi)
            if roi_values.size:
                mean_value = float(np.mean(roi_values))
                label = f"Processed ROI mean {mean_value:.3f}"
                if not self.selecting_roi:
                    self.app.ingest_moke_roi_sample(mean_value)
                    self.app.ingest_2410_roi_sample(mean_value)
                    self.app.ingest_6221_roi_sample(mean_value)
            else:
                label = "ROI outside image"
        return label

    def _draw_roi(self, frame: CameraFrame) -> None:
        roi = self.roi
        if self.selecting_roi and self.roi_start is not None and self.roi_end is not None:
            x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
            y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
            roi = {
                "cx": (x1 + x2) / 2.0,
                "cy": (y1 + y2) / 2.0,
                "w": x2 - x1,
                "h": y2 - y1,
                "angle": 0.0,
            }
        if roi is None or self.mapping is None:
            return
        label = self._ingest_roi_values(frame)
        self._update_roi_overlay(roi, label)

    def _update_roi_overlay(self, roi, label: str) -> None:
        """Create or move the ROI outline without rebuilding the camera image."""
        mapping = self.mapping
        if roi is None or mapping is None:
            return

        def to_canvas(image_x, image_y):
            return (
                mapping["offset_x"]
                + (image_x - mapping["crop_x1"])
                / mapping["crop_width"]
                * mapping["display_width"],
                mapping["offset_y"]
                + (image_y - mapping["crop_y1"])
                / mapping["crop_height"]
                * mapping["display_height"],
            )

        canvas_points = [
            to_canvas(x, y) for x, y in rotated_roi_points(roi)
        ]
        flattened = [
            coordinate for point in canvas_points for coordinate in point
        ]
        if self.roi_overlay_id is None:
            self.roi_overlay_id = self.canvas.create_polygon(
                *flattened,
                outline="#6dff6d",
                fill="",
                width=2,
                tags=("roi_overlay",),
            )
        else:
            self.canvas.coords(self.roi_overlay_id, *flattened)

        label_x, label_y = canvas_points[0]
        label_coordinates = (label_x, max(66, label_y - 5))
        if self.roi_label_id is None:
            self.roi_label_id = self.canvas.create_text(
                *label_coordinates,
                text=label,
                fill="#6dff6d",
                font=(self.app.ui_font_family, self.app.ui_font_size, "bold"),
                anchor="sw",
                tags=("roi_overlay",),
            )
        else:
            self.canvas.coords(self.roi_label_id, *label_coordinates)
            self.canvas.itemconfigure(self.roi_label_id, text=label)
        self.canvas.tag_raise("roi_overlay")

    def _update_selection_overlay(self) -> None:
        if (
            not self.selecting_roi
            or self.roi_start is None
            or self.roi_end is None
        ):
            return
        x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
        y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
        selection = {
            "cx": (x1 + x2) / 2.0,
            "cy": (y1 + y2) / 2.0,
            "w": x2 - x1,
            "h": y2 - y1,
            "angle": 0.0,
        }
        self._update_roi_overlay(
            selection,
            f"Selecting ROI · W {selection['w']:.1f} px · "
            f"H {selection['h']:.1f} px",
        )

    def edit_roi(self, action: str, steps: dict[str, float]) -> None:
        if self.roi is None:
            return
        if action == "rotate_left":
            self.roi["angle"] = (self.roi["angle"] - steps["A"]) % 180.0
        elif action == "rotate_right":
            self.roi["angle"] = (self.roi["angle"] + steps["A"]) % 180.0
        elif action == "width_minus":
            self.roi["w"] = max(2.0, self.roi["w"] - steps["W"])
        elif action == "width_plus":
            self.roi["w"] += steps["W"]
        elif action == "height_minus":
            self.roi["h"] = max(2.0, self.roi["h"] - steps["H"])
        elif action == "height_plus":
            self.roi["h"] += steps["H"]
        elif action == "move_left":
            self.roi["cx"] -= steps["X"]
        elif action == "move_right":
            self.roi["cx"] += steps["X"]
        elif action == "move_up":
            self.roi["cy"] -= steps["Y"]
        elif action == "move_down":
            self.roi["cy"] += steps["Y"]
        if self.latest_frame is not None:
            height, width = self.latest_frame.preview.shape[:2]
            self.roi["cx"] = float(np.clip(self.roi["cx"], 0, width - 1))
            self.roi["cy"] = float(np.clip(self.roi["cy"], 0, height - 1))
            self._draw(self.latest_frame)
        self.app.set_2410_roi(self.roi)

    def _on_image(self, x: int, y: int) -> bool:
        if self.mapping is None:
            return False
        m = self.mapping
        return (
            m["offset_x"] <= x < m["offset_x"] + m["display_width"]
            and m["offset_y"] <= y < m["offset_y"] + m["display_height"]
        )

    def _mouse_wheel(self, event) -> None:
        self._zoom_at(event.x, event.y, 1 if event.delta > 0 else -1)

    def _zoom_at(self, x: int, y: int, direction: int) -> None:
        if not self._on_image(x, y):
            return
        m = self.mapping
        mouse_image_x = m["crop_x1"] + (
            (x - m["offset_x"]) / m["display_width"] * m["crop_width"]
        )
        mouse_image_y = m["crop_y1"] + (
            (y - m["offset_y"]) / m["display_height"] * m["crop_height"]
        )
        old_zoom = self.zoom
        self.zoom = (
            min(self.zoom * ZOOM_FACTOR, MAX_ZOOM)
            if direction > 0
            else max(self.zoom / ZOOM_FACTOR, MIN_ZOOM)
        )
        if self.zoom == old_zoom:
            return
        new_width = m["image_width"] / self.zoom
        new_height = m["image_height"] / self.zoom
        relative_x = (mouse_image_x - m["crop_x1"]) / max(m["crop_width"], 1.0)
        relative_y = (mouse_image_y - m["crop_y1"]) / max(m["crop_height"], 1.0)
        self.center_x = mouse_image_x - relative_x * new_width + new_width / 2.0
        self.center_y = mouse_image_y - relative_y * new_height + new_height / 2.0
        if self.latest_frame is not None:
            self._draw(self.latest_frame)

    def _pan_start(self, event) -> None:
        if not self._on_image(event.x, event.y):
            return
        if event.state & 0x0001:
            if (
                self.app.keithley_scan_running
                or self.app.magnet_scan_running
                or self.app.k6221_scan_running
            ):
                self.app.difference_status_var.set("扫描过程中不能重新选择 ROI")
                return
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is None:
                return
            self.selecting_roi = True
            self.panning = False
            self.roi_start = image_point
            self.roi_end = image_point
            self._update_selection_overlay()
            return
        self.panning = True
        self.pan_start_x = event.x
        self.pan_start_y = event.y
        self.pan_center_x = self.center_x
        self.pan_center_y = self.center_y

    def _pan_move(self, event) -> None:
        if self.selecting_roi:
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is not None:
                self.roi_end = image_point
                self._update_selection_overlay()
            return
        if not self.panning or self.mapping is None:
            return
        m = self.mapping
        self.center_x = self.pan_center_x - (
            event.x - self.pan_start_x
        ) * m["crop_width"] / m["display_width"]
        self.center_y = self.pan_center_y - (
            event.y - self.pan_start_y
        ) * m["crop_height"] / m["display_height"]
        if self.latest_frame is not None:
            self._draw(self.latest_frame)

    def _pan_end(self, event) -> None:
        if self.selecting_roi:
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is not None:
                self.roi_end = image_point
            self.selecting_roi = False
            if self.roi_start is not None and self.roi_end is not None:
                x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
                y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
                if x2 - x1 >= 2 and y2 - y1 >= 2:
                    self.roi = {
                        "cx": (x1 + x2) / 2.0,
                        "cy": (y1 + y2) / 2.0,
                        "w": x2 - x1,
                        "h": y2 - y1,
                        "angle": 0.0,
                    }
                    self.app.set_2410_roi(self.roi)
            if self.latest_frame is not None:
                self._draw(self.latest_frame)
            return
        self.panning = False

    def _clear_roi(self, _event=None) -> None:
        """Clear the shared ROI through the app-level safety interlock."""
        self.app.clear_camera_roi()

    def clear_roi_selection(self) -> None:
        """Remove only the Camera Live ROI state and its Canvas overlay."""
        self.selecting_roi = False
        self.panning = False
        self.roi_start = None
        self.roi_end = None
        self.roi = None
        self.canvas.delete("roi_overlay")
        self.roi_overlay_id = None
        self.roi_label_id = None
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)

    def _toggle_contrast(self, _event=None) -> None:
        automatic = self.worker.toggle_contrast()
        self.app.append_log("相机对比度：" + ("自动" if automatic else "固定"))

    def toggle_background(self) -> bool:
        previous = self.worker.background_mode
        enabled = self.worker.toggle_background()
        mode = self.worker.background_mode
        if mode != "off" and mode != previous:
            self.app.reset_difference_live_time_window()
        mode_label = {"off": "关闭", "plain": "普通差分", "tracking": "漂移追踪差分"}[mode]
        self.app.append_log("差分模式：" + mode_label)
        return enabled

    def set_background_mode(self, mode: str) -> str:
        previous = self.worker.background_mode
        selected = self.worker.set_background_mode(mode)
        if selected != "off" and selected != previous:
            self.app.reset_difference_live_time_window()
        mode_label = {"off": "关闭", "plain": "普通差分", "tracking": "漂移追踪差分"}[selected]
        self.app.append_log("差分模式：" + mode_label)
        return selected

    def capture_background(self) -> None:
        self.worker.capture_background()
        self.app.reset_difference_live_time_window(restart_clock=True)
        self.app.append_log("正在用下一帧重新采集背景…")

    def _toggle_background(self, _event=None) -> None:
        if (
            self.app.keithley_scan_running
            or self.app.magnet_scan_running
            or self.app.k6221_scan_running
        ):
            self.app.difference_status_var.set("扫描过程中不能切换差分模式")
            return
        self.toggle_background()

    def _capture_background(self, _event=None) -> None:
        if (
            self.app.keithley_scan_running
            or self.app.magnet_scan_running
            or self.app.k6221_scan_running
        ):
            self.app.difference_status_var.set("扫描过程中不能重新采集背景")
            return
        self.capture_background()

    def _reset_zoom(self, _event=None) -> None:
        self.zoom = 1.0
        self.center_x = None
        self.center_y = None
        if self.latest_frame is not None:
            self._draw(self.latest_frame)


class CombinedControlApp:
    """Tk LED panel with a strictly main-thread UI event queue."""

    def __init__(self, root: tk.Tk) -> None:
        self.root = root
        self.root.title(MAIN_WINDOW_TITLE)
        self.window_layout = calculate_window_layout(self.root)
        self.ui_scale = float(self.window_layout["ui_scale"])
        self.canvas_scale = float(self.window_layout["canvas_scale"])
        setattr(self.root, "_moke_ui_scale", self.ui_scale)
        self.root.geometry(geometry_string(self.window_layout["control"]))
        control_geometry = self.window_layout["control"]
        self.root.minsize(
            min(control_geometry[0], max(620, int(760 * self.ui_scale))),
            min(control_geometry[1], max(500, int(650 * self.ui_scale))),
        )
        screen_width, screen_height = self.window_layout["screen"]
        self.root.maxsize(screen_width, screen_height)
        self.root.bind_all(
            "<FocusIn>", self._enforce_english_input_mode, add="+"
        )
        self.root.after_idle(lambda: force_english_input_mode(self.root))

        self.ui_queue: queue.Queue[Callable[[], None]] = queue.Queue()
        self.controller = LEDSerialController(self.thread_log)
        self.executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="led-io")
        # File exports never share an executor with any instrument.  A slow
        # disk/network folder therefore cannot delay LED, motor, magnet or
        # source-meter commands.
        self.file_executor = ThreadPoolExecutor(
            max_workers=1, thread_name_prefix="file-export"
        )
        self.active_file_exports: set[str] = set()
        self.busy = False
        self.closing = False
        self.instrument_connection_indicators: dict[
            str, tuple[tk.Canvas, int]
        ] = {}

        self.port_var = tk.StringVar(value=DEFAULT_PORT)
