    def save_plot_canvas_snapshot(self, canvas: tk.Canvas, path: Path) -> None:
        """Save the currently visible relation-plot canvas as a PNG screenshot."""
        if ImageGrab is None:
            raise RuntimeError("保存图窗快照需要 Pillow 的 ImageGrab 模块")
        self.root.update_idletasks()
        width = int(canvas.winfo_width())
        height = int(canvas.winfo_height())
        if width <= 1 or height <= 1 or not canvas.winfo_ismapped():
            raise RuntimeError("关系图当前不可见，无法截取图窗")
        left = int(canvas.winfo_rootx())
        top = int(canvas.winfo_rooty())
        destination = Path(path)
        destination.parent.mkdir(parents=True, exist_ok=True)
        bbox = (left, top, left + width, top + height)
        try:
            snapshot = ImageGrab.grab(bbox=bbox, all_screens=True)
        except TypeError:
            # Compatibility with older Pillow releases without all_screens.
            snapshot = ImageGrab.grab(bbox=bbox)
        snapshot.save(destination, format="PNG")

    def select_csv_save_directory(
        self,
        title: str,
        previous_directory: Path,
    ) -> Path | None:
        """Ask for a result directory and return None when the user cancels."""
        previous = Path(previous_directory)
        initial_directory = previous if previous.is_dir() else previous.parent
        if not initial_directory.is_dir():
            initial_directory = Path(__file__).resolve().parent
        selected = filedialog.askdirectory(
            parent=self.root,
            title=title,
            initialdir=str(initial_directory),
            mustexist=True,
        )
        if not selected:
            return None
        return Path(selected)

